#!/usr/bin/env node
// MI-099 — PIET frontend DOM test runner (headless, CI-style RED/GREEN).
//
// Loads the REAL frontend ES modules (../js/console.js, ../js/graph.js) inside a
// jsdom DOM and asserts the bug-fix invariants against AUTHENTIC fixtures that were
// generated by the PIET backend dispatcher (fixtures/dom/*.json — real cobra output
// through the same code path the app uses). No mock numbers, no self-referential blocks.
//
//   BUG-017  coeftable header letter: logit/probit → z / P>|z|  ;  OLS family → t / P>|t|
//            Tightened: bare stat-letter col header (z vs t) + direct contrast showing
//            z→t swap is the ONLY difference between logit and feols header rows.
//   BUG-010  multi-line paste → N separate command submits (onInputPaste split logic)
//   BUG-007/009  marginsplot point-count == margins dydx(*) target count
//
// Exit 0 = all green; exit 1 = one or more failures (for CI gating).
//
// Negative-control self-test: DOM_RUNNER_SELFTEST=1 intentionally injects one wrong
// assertion to prove the runner can go RED (guards against a vacuously-green gate).
//
// Suite-registration floor (REDTEAM-P2 blind spot ③, GATE-FALSIFICATION §3c): the
// per-check count N has no floor and grows with fixtures, so a suite() call that
// silently stops running (commented out, gated behind a false condition, deleted)
// just reports a smaller, still-green N — nothing before this caught that. The
// runner diffs the suite names that actually ran against dom_runner.suites.json;
// a name in the manifest that didn't run this pass is RED regardless of check
// count. A NEW suite name not yet in the manifest is only noted, never fatal — the
// floor must never block normal growth. Regenerate after an intentional add/
// remove/rename:  DOM_RUNNER_UPDATE_MANIFEST=1 node dom_runner.mjs
//
// Usage:  node dom_runner.mjs            (from frontend/test/)
//         npm test                       (after `npm install`)
//         DOM_RUNNER_SELFTEST=1 node dom_runner.mjs   (must exit 1)
//         DOM_RUNNER_UPDATE_MANIFEST=1 node dom_runner.mjs   (regenerate the suite manifest)

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { JSDOM } from 'jsdom';

const __dirname = dirname(fileURLToPath(import.meta.url));
const FIX = (p) => resolve(__dirname, '../../fixtures', p);
const JS  = (p) => pathToFileURL(resolve(__dirname, '../js', p)).href;
// REDTEAM-P2 blind spot ③ (GATE-FALSIFICATION §3c): check counts have no floor and
// grow with fixtures, so a suite that silently stops registering just reports a
// smaller, still-green N. This is the registered-suite manifest that closes it —
// see the comparison right before the report section, below.
const SUITE_MANIFEST = resolve(__dirname, 'dom_runner.suites.json');

// ── jsdom global DOM (the frontend modules use document.* at module scope only
//    inside functions, so a single shared document is sufficient and faithful). ──
// url: jsdom's localStorage throws a SecurityError on the default about:blank
// (opaque origin) — a real origin is required by the paste-pref suite below,
// which drives app.js's localStorage-persisted 'piet-paste-autorun' preference.
const dom = new JSDOM('<!DOCTYPE html><html><body></body></html>', {
  pretendToBeVisual: true,
  url: 'http://localhost/',
});
globalThis.window = dom.window;
globalThis.document = dom.window.document;
// navigator is read-only on globalThis in Node ≥21; define it non-destructively
// only if absent (the frontend modules don't depend on it for these suites).
if (!('navigator' in globalThis)) {
  Object.defineProperty(globalThis, 'navigator', { value: dom.window.navigator, configurable: true });
}
// app.js resolves bare `localStorage`/`location` identifiers. Node ≥22 exposes
// a configurable globalThis.localStorage getter that yields undefined unless
// --localstorage-file is passed (and defines no `location` at all) — pin BOTH
// to jsdom's so app.js and the paste-pref suite's assertions share one store.
Object.defineProperty(globalThis, 'localStorage', { value: dom.window.localStorage, configurable: true });
if (!('location' in globalThis)) {
  Object.defineProperty(globalThis, 'location', { value: dom.window.location, configurable: true });
}
// SVG via createElementNS is supported by jsdom; graph.js relies on it.

// WS-F2 mission 1 (A3-01 JS side): graph.js now reads --graph-accent-1/-2 and
// --series-1..-8 via the bare global getComputedStyle() at render time (mirrors
// what a real browser exposes on window). jsdom doesn't put it on globalThis by
// default — without this, every renderTwoway()/renderXtline() call below throws.
globalThis.getComputedStyle = dom.window.getComputedStyle.bind(dom.window);

// UX-047: app.js's init() registers a bare global `MutationObserver` (the
// "grid show/hide adapter" watching #browser-overlay's `hidden` attribute —
// real browsers/WKWebView expose it unqualified on window, same as
// getComputedStyle above). jsdom implements it but doesn't put it on
// globalThis by default.
globalThis.MutationObserver = dom.window.MutationObserver;

// Load the REAL piet.css (WS-C1 ground truth) so the A3-01 regression-guard
// suite below can check the actual --graph-accent-1/-2 token definitions, and
// set the shipped-default `data-mode="boring"` on <html> (mirrors index.html's
// pre-paint boot script) so :root-scoped tokens resolve the same way they do
// in the app's default UI.
dom.window.document.head.innerHTML =
  `<style>${readFileSync(resolve(__dirname, '../css/piet.css'), 'utf8')}</style>`;
dom.window.document.documentElement.setAttribute('data-mode', 'boring');

// api.js (imported transitively by console.js) calls getCachedPietVersion(); it
// must not touch the network. It reads a module-level cache that defaults to null,
// which is the safe degraded path — no fetch happens at import or in formatEstimation.

// ── tiny assertion harness ──────────────────────────────────────────────────
let FAILS = 0, PASSES = 0;
const results = [];
function suite(name, fn) {
  const ctx = { name, fails: 0 };
  try { fn(ctx); }
  catch (e) { ctx.fails++; FAILS++; results.push(['THROW', name, String(e && e.stack || e)]); }
  results.push(['SUITE', name, ctx.fails === 0 ? 'green' : `${ctx.fails} failed`]);
}
function check(ctx, cond, msg) {
  if (cond) { PASSES++; results.push(['PASS', ctx.name, msg]); }
  else      { FAILS++; ctx.fails++; results.push(['FAIL', ctx.name, msg]); }
}

function loadFix(p) { return JSON.parse(readFileSync(FIX(p), 'utf8')); }

// ── load the real modules ────────────────────────────────────────────────────
const { formatEstimation, formatCorrelate, formatSummarize, formatDescribe,
        initConsole, appendBlock, getGraphs, getGraphGalleryElidedCount, getGraphDroppedCount, setGraphSpillMaxBytes,
        clearConsole, clearGraphGallery,
        setGraphSpill, getGraphEntries, getGraphById, getGraphsAsync, getGraphSpilledCount, flushGraphSpill,
        setMemoryBudgetMb, DEFAULT_MEMORY_BUDGET_MB, noviceErrorHint } = await import(JS('console.js'));
const { renderGraph } = await import(JS('graph.js'));
const { createSpill } = await import(JS('graph_spill.js'));
// fmtG: reused (not reimplemented) so BS-022/BS-026 value assertions below derive
// their expected strings from the SAME formatter console.js renders with — no
// hand-typed number literals to drift out of sync with util.js.
const { fmtG } = await import(JS('util.js'));

// ════════════════════════════════════════════════════════════════════════════
// BUG-017 — coeftable header stat letter (z for MLE, t for OLS family)
//   Fixtures are REAL dispatcher output: logit/probit (z) and the feols goldens (t).
// ════════════════════════════════════════════════════════════════════════════
suite('BUG-017: logit/probit coeftable header → z / P>|z| (real dispatcher fixture)', (ctx) => {
  // headerLine() extracts the column-header row (the one with Coef. / Std. Err.)
  // from formatEstimation() output — that is the one line where tHdr and pHdr appear.
  function headerLine(text) {
    return text.split('\n').find(l => l.includes('Coefficient') && l.includes('Std. err.')) ?? '';
  }
  // zHdrRe matches the EXACT column-header sequence built by console.js L362-363:
  //   padL(tHdr, tW+3)   →  right-aligned 'z' (min 3+1 spaces then 'z')
  //   padL(pHdr, pW+3)   →  right-aligned 'P>|z|' (with leading spaces)
  // Using \s+ between Std. Err. and the bare letter catches any column width.
  const zHdrRe = /Std\. err\.\s+z\s+P>\|z\|/;
  const tHdrRe = /Std\. err\.\s+t\s+P>\|t\|/;

  for (const [fx, est] of [['dom/logit_estimation.json', 'logit'],
                           ['dom/probit_estimation.json', 'probit']]) {
    const block = loadFix(fx);
    check(ctx, block.estimator === est, `${fx} carries estimator="${est}" (got "${block.estimator}")`);
    const text = formatEstimation(block);
    const hdr  = headerLine(text);
    check(ctx, text.includes('P>|z|'), `${est}: header shows P>|z|`);
    check(ctx, !text.includes('P>|t|'), `${est}: header does NOT show P>|t|`);
    // Tightened BUG-017: bare stat-letter column header is 'z', not 't'
    check(ctx, zHdrRe.test(hdr),
      `${est}: column header contains standalone 'z' between Std. Err. and P>|z| (got: ${JSON.stringify(hdr)})`);
    check(ctx, !tHdrRe.test(hdr),
      `${est}: column header does NOT contain standalone 't' sequence (got: ${JSON.stringify(hdr)})`);
    check(ctx, !/\bundefined\b/.test(text), `${est}: no "undefined" in output`);
  }
});

suite('BUG-017: OLS-family coeftable header → t / P>|t| (real feols goldens)', (ctx) => {
  // The golden fixtures are raw cobra --tidy (no top-level estimator drives the title
  // the same way), so we assert via reconstructed estimation blocks that mirror the
  // dispatcher's normalized shape for the OLS family, plus the dispatcher margins block.
  function headerLine(text) {
    return text.split('\n').find(l => l.includes('Coefficient') && l.includes('Std. err.')) ?? '';
  }
  const zHdrRe = /Std\. err\.\s+z\s+P>\|z\|/;
  const tHdrRe = /Std\. err\.\s+t\s+P>\|t\|/;

  const olsBlocks = [
    { type: 'estimation', estimator: 'feols', depvar: 'price', n_obs: 74, r2: 0.29,
      coeftable: loadFix('golden/feols_plain.json').coeftable },
    { type: 'estimation', estimator: 'feols', depvar: 'price', n_obs: 74, r2: 0.30,
      coeftable: loadFix('golden/feols_robust.json').coeftable },
  ];
  for (const b of olsBlocks) {
    const text = formatEstimation(b);
    const hdr  = headerLine(text);
    check(ctx, text.includes('P>|t|'), `${b.estimator}: header shows P>|t|`);
    check(ctx, !text.includes('P>|z|'), `${b.estimator}: header does NOT show P>|z|`);
    // Tightened BUG-017: bare stat-letter column header is 't', not 'z'
    check(ctx, tHdrRe.test(hdr),
      `${b.estimator}: column header contains standalone 't' between Std. Err. and P>|t| (got: ${JSON.stringify(hdr)})`);
    check(ctx, !zHdrRe.test(hdr),
      `${b.estimator}: column header does NOT contain standalone 'z' sequence (got: ${JSON.stringify(hdr)})`);
  }
});

// ── BUG-017 direct contrast: z vs t stat-letter switches on estimator ────────
// Uses the same shared coeftable rows for logit vs reg/feols so the ONLY source
// of difference is the estimator field driving statLetter().  Asserts:
//   (a) logit header line contains 'z'  and reg/feols header line contains 't'
//   (b) the two header lines DIFFER in exactly the stat-letter column position
//       (i.e. replace('z','t') in the logit header == the feols header modulo
//        depvar-width padding — proven by showing the z/t swap is the difference).
suite('BUG-017: z vs t stat-letter switches on estimator (direct contrast)', (ctx) => {
  function headerLine(text) {
    return text.split('\n').find(l => l.includes('Coefficient') && l.includes('Std. err.')) ?? '';
  }
  // Shared coeftable — identical rows used for both estimators.
  const ct = [
    { name: 'mpg',    b: -0.169, se: 0.092, t: -1.83, p: 0.067, ci_lo: -0.349, ci_hi: 0.012 },
    { name: 'weight', b: -0.004, se: 0.001, t: -3.86, p: 0.000, ci_lo: -0.006, ci_hi: -0.002 },
    { name: '_cons',  b: 13.708, se: 4.519, t:  3.03, p: 0.002, ci_lo:  4.832, ci_hi: 22.585 },
  ];
  const depvar = 'foreign';

  const logitText = formatEstimation({ type: 'estimation', estimator: 'logit',  depvar, n_obs: 74, coeftable: ct });
  const feolsText = formatEstimation({ type: 'estimation', estimator: 'feols',  depvar, n_obs: 74, coeftable: ct });
  const regText   = formatEstimation({ type: 'estimation', estimator: 'reg',    depvar, n_obs: 74, coeftable: ct });

  const logitHdr = headerLine(logitText);
  const feolsHdr = headerLine(feolsText);
  const regHdr   = headerLine(regText);

  // (a) stat-letter assertions on each header
  check(ctx, /Std\. err\.\s+z\s+P>\|z\|/.test(logitHdr),
    `contrast: logit header has standalone 'z' col (got: ${JSON.stringify(logitHdr)})`);
  check(ctx, /Std\. err\.\s+t\s+P>\|t\|/.test(feolsHdr),
    `contrast: feols header has standalone 't' col (got: ${JSON.stringify(feolsHdr)})`);
  check(ctx, /Std\. err\.\s+t\s+P>\|t\|/.test(regHdr),
    `contrast: reg header has standalone 't' col (got: ${JSON.stringify(regHdr)})`);

  // (b) the two header lines differ — the stat-letter switch IS the difference.
  //     Same depvar + coeftable → same column widths → identical header except z/t.
  //     Replacing the z-family tokens with t-family tokens in the logit header
  //     must produce the feols header exactly.
  const logitHdrNorm = logitHdr.replace(/\bz\b/g, 't').replace('P>|z|', 'P>|t|');
  check(ctx, logitHdrNorm === feolsHdr,
    `contrast: logit header with z→t swap equals feols header exactly\n` +
    `  logit (z):    ${JSON.stringify(logitHdr)}\n` +
    `  feols (t):    ${JSON.stringify(feolsHdr)}\n` +
    `  logit z→t:   ${JSON.stringify(logitHdrNorm)}`);

  // (c) sanity: the headers before normalization are genuinely different
  check(ctx, logitHdr !== feolsHdr,
    `contrast: logit and feols header lines differ (z vs t distinguishes them)`);
});

// ── BUG-017 full estimator matrix ─────────────────────────────────────────────
// These arrays are ported exactly from bugs_render_test.html ~line 431-440.
// This suite is the authoritative BUG-017 coverage for ALL estimators the UI knows.
suite('BUG-017: full estimator matrix — z for MLE/2SLS/SUR/RE/TS, t for OLS family', (ctx) => {
  const ct = [
    { name: 'x1', b: 1.0, se: 0.1, t: 10.0, p: 0.000, ci_lo: 0.8, ci_hi: 1.2 },
    { name: '(intercept)', b: 0.5, se: 0.2, t: 2.5, p: 0.012, ci_lo: 0.1, ci_hi: 0.9 },
  ];
  const mk = (est) => formatEstimation({
    type: 'estimation', estimator: est, depvar: 'y', n_obs: 100, r2: 0.5, coeftable: ct,
  });

  // Ported exactly from bugs_render_test.html zEstimators array (~line 432):
  const zEstimators = [
    'logit','logistic','probit','cloglog','poisson','fepois','ppmlhdfe','nbreg',
    'tobit','heckman','glm','mlogit','ologit','oprobit','truncreg',
    'xtlogit','xtprobit','xtpoisson','xtnbreg','xtreg_re','xtreg',
    'iv','iv2sls','iv2sls_multi','ivregress','reg3','sureg','arima','arch','var','vec',
  ];
  // Ported exactly from bugs_render_test.html tEstimators array (~line 437):
  const tEstimators = [
    'feols','feols_multi','ols','reg','r','regress','areg',
    'xtreg_fe','xtreg_be','newey','prais','qreg','sqreg','iqreg',
  ];

  for (const est of zEstimators) {
    const text = mk(est);
    check(ctx, text.includes('P>|z|') && !text.includes('P>|t|'),
      `${est} → z / P>|z|`);
  }
  for (const est of tEstimators) {
    const text = mk(est);
    check(ctx, text.includes('P>|t|') && !text.includes('P>|z|'),
      `${est} → t / P>|t|`);
  }
});

// ── BUG-205(1) — `lincom` keys z/t on the FIT (vcov_type), not on the verb ────
// `lincom`'s own estimator label never changes with what it was computed
// FROM, so it is deliberately excluded from the estimator-matrix suite above.
// The engine's post-estimation refit carries `vcov_type: 'oim'` only on the
// ML (logit/probit/poisson) path; the least-squares refit (after regress)
// carries 'iid'/'robust'/'hc1'/'cluster(...)' — same family the OLS-family
// full table itself reports t under. `nlcom` is a same-file regression guard:
// it must stay z regardless of vcov_type (Stata's nlcom is always a
// delta-method z, even after `regress`), so it should never gain lincom's
// verb-keyed mistake in reverse.
suite("BUG-205(1): lincom keys z/t on vcov_type (the fit), not on the verb 'lincom'", (ctx) => {
  const ct = [
    { name: 'x1', b: 1.0, se: 0.1, t: 10.0, p: 0.000, ci_lo: 0.8, ci_hi: 1.2 },
  ];
  const mkLincom = (vcov_type) => formatEstimation({
    type: 'estimation', estimator: 'lincom', depvar: '', n_obs: 100, coeftable: ct, vcov_type,
  });

  {
    const text = mkLincom('oim');
    check(ctx, text.includes('P>|z|') && !text.includes('P>|t|'),
      "lincom vcov_type='oim' (post-logit/probit/poisson refit) → z / P>|z|, not t");
  }
  for (const vc of ['iid', 'robust', 'hc1', 'cluster(state)']) {
    const text = mkLincom(vc);
    check(ctx, text.includes('P>|t|') && !text.includes('P>|z|'),
      `lincom vcov_type='${vc}' (post-regress refit) → t / P>|t|, not z`);
  }

  const mkNlcom = (vcov_type) => formatEstimation({
    type: 'estimation', estimator: 'nlcom', depvar: '', n_obs: 100, coeftable: ct, vcov_type,
  });
  for (const vc of ['iid', 'oim']) {
    const text = mkNlcom(vc);
    check(ctx, text.includes('P>|z|') && !text.includes('P>|t|'),
      `nlcom regression guard, vcov_type='${vc}' → still z / P>|z| (unaffected by BUG-205(1))`);
  }
});

// ════════════════════════════════════════════════════════════════════════════
// BUG-007/009 — marginsplot renders exactly one point per dydx() target
//   Cross-checked: marginsplot point-count == margins-block AME term count.
//   Two cases: 2-target (mpg+weight) and 3-target (mpg+weight+length).
// ════════════════════════════════════════════════════════════════════════════
function runMarginsplotCase(ctx, graphFile, marginsFile, label) {
  const mplot  = loadFix(graphFile);
  const margins = loadFix(marginsFile);

  // Ground-truth target count: AME coeftable rows excluding the intercept.
  const ameTerms = (margins.coeftable || [])
    .map((c) => c.name).filter((n) => n && n !== '(intercept)');
  check(ctx, ameTerms.length >= 1, `[${label}] margins block has ≥1 AME term (got ${ameTerms.length})`);

  // The marginsplot block must carry exactly that many points, by name.
  const plotNames = (mplot.points || []).map((p) => p.name);
  check(ctx, plotNames.length === ameTerms.length,
    `[${label}] marginsplot points (${plotNames.length}) == dydx targets (${ameTerms.length})`);
  check(ctx, JSON.stringify([...plotNames].sort()) === JSON.stringify([...ameTerms].sort()),
    `[${label}] marginsplot point names == AME term names (plot=${JSON.stringify(plotNames)}, ame=${JSON.stringify(ameTerms)})`);

  // And the rendered SVG must draw exactly that many point estimates (class g-point).
  const el  = renderGraph(mplot);
  const svg = el.querySelector('svg');
  check(ctx, !!svg, `[${label}] renderGraph produced an <svg> for marginsplot`);
  const dots = svg.querySelectorAll('circle.g-point');
  check(ctx, dots.length === ameTerms.length,
    `[${label}] SVG draws ${dots.length} point estimate dots == ${ameTerms.length} dydx targets`);

  // Each target name must appear as an x-axis label (so nothing is silently dropped).
  const xLabels = Array.from(svg.querySelectorAll('text.g-ticklabel')).map((t) => t.textContent.trim());
  for (const name of ameTerms) {
    check(ctx, xLabels.includes(name), `[${label}] marginsplot x-axis label "${name}" present`);
  }
}

suite('BUG-007/009: marginsplot point-count == margins dydx(*) target count', (ctx) => {
  // Case 1: 2-target fixture (mpg + weight) — original.
  runMarginsplotCase(ctx,
    'dom/marginsplot_graph.json',
    'dom/margins_estimation.json',
    '2-target',
  );
  // Case 2: 3-target fixture (mpg + weight + length) — generated from auto.hbin.
  runMarginsplotCase(ctx,
    'dom/marginsplot3_graph.json',
    'dom/margins3_estimation.json',
    '3-target',
  );
});

// ════════════════════════════════════════════════════════════════════════════
// BUG-052 — coefplot renders its coefficients (FE stored model + plain OLS).
//   Root cause: kind:"coefplot" had NO renderer branch → fell through to
//   renderScatter → empty axes, footer "n = ?". Guards the renderCoefplot
//   wiring so a coefplot block draws one g-point per coef (and never "n = ?").
//   Fixtures are authentic backend output (piet_native --do through dispatch).
// ════════════════════════════════════════════════════════════════════════════
function runCoefplotCase(ctx, graphFile, label) {
  const block = loadFix(graphFile);
  const nCoefs = (block.models || []).reduce((s, m) => s + (m.coefs || []).length, 0);
  check(ctx, nCoefs >= 1, `[${label}] coefplot block has ≥1 coef (got ${nCoefs})`);

  const el  = renderGraph(block);
  const svg = el.querySelector('svg');
  check(ctx, !!svg, `[${label}] renderGraph produced an <svg> for coefplot`);
  const dots = svg.querySelectorAll('circle.g-point');
  check(ctx, dots.length === nCoefs,
    `[${label}] SVG draws ${dots.length} point estimate dots == ${nCoefs} coefs`);

  // Each coef name must appear as a y-axis label (nothing silently dropped).
  const labels = Array.from(svg.querySelectorAll('text.g-ticklabel')).map((t) => t.textContent.trim());
  for (const m of block.models) {
    for (const c of (m.coefs || [])) {
      check(ctx, labels.includes(c.name), `[${label}] coefplot y-axis label "${c.name}" present`);
    }
  }

  // Footer must NOT degrade to the "n = ?" placeholder (BUG-052 secondary symptom).
  const cap = el.querySelector('.g-caption')?.textContent || '';
  check(ctx, !/n\s*=\s*\?/.test(cap), `[${label}] coefplot footer is not "n = ?" (got "${cap}")`);
}

suite('BUG-052: coefplot renders one point per coefficient (FE + OLS)', (ctx) => {
  // FE stored model (xtreg,fe) — the exact class the User canary failed on.
  runCoefplotCase(ctx, 'dom/coefplot_fe_graph.json', 'FE stored model');
  // Plain OLS — positive control (was ALSO empty in the GUI; not FE-specific).
  runCoefplotCase(ctx, 'dom/coefplot_ols_graph.json', 'plain OLS');
});

// ════════════════════════════════════════════════════════════════════════════
// BUG-010 — multi-line paste → loaded into the do-file editor (design decision 4).
//   onInputPaste is not exported; we test the SAME decision logic it uses (the
//   ≥2-non-empty-lines threshold is UNCHANGED — only the ACTION changed: by
//   default it loads the block into the do-file editor, foreground, no
//   execution; the opt-in 'piet-paste-autorun' preference restores the old
//   run-immediately behavior — BOTH actions are integration-tested end-to-end
//   in the "Paste pref" suite below). Asserting the effective-line count and
//   the routing decision for representative pastes.
// ════════════════════════════════════════════════════════════════════════════
suite('BUG-010: multi-line paste routes to the do-editor (no auto-run, design decision 4)', (ctx) => {
  // Mirror of onInputPaste's decision: normalize CRLF, count non-empty lines.
  function effectiveCommandCount(raw) {
    const text = raw.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    if (!text.includes('\n')) return 1;            // single-line: browser default (1 cmd)
    return text.split('\n').filter((l) => l.trim()).length;
  }
  function routesToDoEditor(raw) {
    const text = raw.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    if (!text.includes('\n')) return false;
    return text.split('\n').filter((l) => l.trim()).length >= 2;
  }

  const threeCmds = 'regress price mpg\nregress price weight\nsummarize price';
  check(ctx, effectiveCommandCount(threeCmds) === 3, '3-line paste → 3 effective lines');
  check(ctx, routesToDoEditor(threeCmds), '3-line paste routes to the do-editor (not collapsed to 1)');

  const withBlankLines = 'use auto\n\nregress price mpg\n\n\nlist price';
  check(ctx, effectiveCommandCount(withBlankLines) === 3, 'blank lines ignored → 3 effective lines');

  const crlf = 'logit foreign mpg\r\nmargins, dydx(*)\r\nmarginsplot';
  check(ctx, effectiveCommandCount(crlf) === 3, 'CRLF paste normalized → 3 effective lines');
  check(ctx, routesToDoEditor(crlf), 'CRLF multi-line routes to the do-editor');

  const single = 'regress price mpg weight';
  check(ctx, effectiveCommandCount(single) === 1, 'single-line paste → 1 effective line (browser default insert)');
  check(ctx, !routesToDoEditor(single), 'single-line paste does NOT route to the do-editor');

  const oneEffective = 'regress price mpg\n   \n';
  check(ctx, !routesToDoEditor(oneEffective), 'one effective line + trailing blank → browser default (not do-editor)');
});

