suite('WS1: correlate renders Stata lower-triangular matrix', (ctx) => {
  // estimator==='corr', method==='correlate' → formatCorrelate (matrix forwarded by dispatcher).
  const block = {
    type: 'estimation', estimator: 'corr', method: 'correlate', pairwise: false, sig: false,
    n_obs: 941, variables: ['y', 'x1', 'x2'],
    r: [[1.0, 0.3720, 0.0204], [0.3720, 1.0, 0.4704], [0.0204, 0.4704, 1.0]],
  };
  const text = formatCorrelate(block);
  const lines = text.split('\n');
  check(ctx, text.startsWith('(obs=941)'), `correlate prints "(obs=941)" header`);
  // var names appear as both row stubs and column headers
  check(ctx, /\by\b/.test(text) && /\bx1\b/.test(text) && /\bx2\b/.test(text), `all 3 var names present`);
  // diagonal is 1.0000
  check(ctx, (text.match(/1\.0000/g) || []).length === 3, `three 1.0000 diagonal entries`);
  // lower-triangular: the y row has exactly one number, the x2 row has three
  const yRow  = lines.find(l => /^\s*y\s*│/.test(l)) || '';
  const x2Row = lines.find(l => /^\s*x2\s*│/.test(l)) || '';
  check(ctx, (yRow.match(/-?\d\.\d{4}/g) || []).length === 1, `y row has 1 coefficient (lower-triangular)`);
  check(ctx, (x2Row.match(/-?\d\.\d{4}/g) || []).length === 3, `x2 row has 3 coefficients (lower-triangular)`);
  check(ctx, text.includes('0.3720'), `off-diagonal r(y,x1)=0.3720 rendered`);
});

