// A representative event-study twoway block (rarea band + connected fit + yline)
function _twowayFixture(name) {
  return {
    type: 'graph', kind: 'twoway',
    title: 'Event study', subtitle: '', x_label: 'rel_time', y_label: 'att',
    x_min: -3, x_max: 3, y_min: -1.5, y_max: 2.5,
    layers: [
      { kind: 'rarea',
        band: [[-3, -1.0, 0.5], [-2, -0.8, 0.7], [-1, -0.5, 0.9],
               [0, -0.2, 1.4], [1, 0.1, 1.8], [2, 0.3, 2.2], [3, 0.4, 2.5]],
        style: { fcolor: '#1850a8', opacity: 0.15, lcolor: 'none', lwidth: 0 } },
      { kind: 'connected',
        points: [[-3, -0.25], [-2, -0.05], [-1, 0.2], [0, 0.6],
                 [1, 0.95], [2, 1.25], [3, 1.45]],
        style: { color: '#1850a8', opacity: 1.0, lwidth: 2.6, lpattern: null,
                 msymbol: 'circle', msize: 1.6, hollow: false, mcolor: '#1850a8' } },
    ],
    axes: { xline: [0], yline: [0], xscale_noline: true, yscale_noline: false,
            xlabel_none: false, ylabel_none: false },
    legend: { order: [[1, 'pooled'], [0, 'CI']], cols: 1, size: 'vsmall', off: false },
    name: name || null, n_obs: 14, suppressed: false,
  };
}

suite('Stage-4: multi-layer twoway renders one composited SVG (rarea + connected)', (ctx) => {
  const block = _twowayFixture('diff_panel');
  const el = renderGraph(block);
  const svg = el.querySelector('svg');
  check(ctx, svg != null, `renderGraph(twoway) produces an <svg>`);
  check(ctx, (svg.getAttribute('viewBox') || '').split(/\s+/).length === 4,
    `twoway <svg> carries a 4-part viewBox (PNG-export sizing)`);
  // rarea band → a filled <path> with fill-opacity; connected fit → a stroked <path>.
  const paths = [...svg.querySelectorAll('path')];
  const banded = paths.some(p => (p.getAttribute('fill-opacity') || '') !== '' &&
                                  p.getAttribute('fill') !== 'none');
  check(ctx, banded, `rarea layer emits a filled band <path> with fill-opacity`);
  const stroked = paths.some(p => p.getAttribute('fill') === 'none' &&
                                  (p.getAttribute('stroke') || '') !== 'none');
  check(ctx, stroked, `connected layer emits a stroked line <path>`);
  // connected markers → at least one <circle>.
  check(ctx, svg.querySelectorAll('circle').length >= 1,
    `connected layer emits per-point markers (<circle>)`);
  // legend rendered with two entries (labels present).
  const txt = svg.textContent || '';
  check(ctx, txt.includes('pooled') && txt.includes('CI'),
    `legend(order(...)) labels render ("pooled", "CI")`);
});

