// ════════════════════════════════════════════════════════════════════════════
// P7 — console scrollback cap (COUNCIL-20260710 D5/F6): a runaway `.do` loop
//   must not be able to grow the console DOM without bound. appendBlock()
//   caps live blocks by BOTH a byte budget and a block count (derived from
//   memoryBudgetMb — console.js's consoleCaps()/DEFAULT_MEMORY_BUDGET_MB);
//   whichever trips first, the OLDEST live blocks are dropped and collapsed
//   into one "…older output trimmed (N blocks)" marker. Two legs:
//     (A) tiny budget -> the BLOCK-COUNT dimension binds first (many tiny
//         blocks). The required leg per spec: marker renders, and content
//         that survives the cap is byte-identical to the same block
//         rendered with zero cap pressure.
//     (B) moderate budget + large blocks -> the BYTE dimension binds first
//         while block count alone would not have tripped — proves bytes are
//         an independently functioning constraint, not just window dressing
//         alongside the block-count one.
//   Exact trim points below (5/195 survivors/elided for A; 258/142 for B)
//   were derived by simulating consoleCaps()'s formula + the same oldest-
//   first trim loop out-of-band (see the P7 implementation task) — pinning
//   them turns this into a real regression guard, not just a shape check.
// ════════════════════════════════════════════════════════════════════════════
suite('P7: console cap (block-count-bound) trims oldest blocks, keeps survivors byte-identical to uncapped', (ctx) => {
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  let body = document.getElementById('console-body');
  initConsole(body, document.getElementById('console-empty'), null);
  clearConsole();

  // mb=5/24 -> byteBudget=2185 B, blockCount=5 (consoleCaps()). 200 tiny echo
  // blocks (~30-36 B of JSON each) total well under 2185 B even summed over
  // all 5 survivors, so the BLOCK-COUNT dimension is what actually binds.
  setMemoryBudgetMb(5 / 24);
  const N = 200;
  const mk = (i) => ({ type: 'echo', text: `display ${i}` });
  for (let i = 0; i < N; i++) appendBlock(mk(i));

  const marker = body.querySelector('.block-elision');
  check(ctx, marker != null, 'elision marker rendered once the cap trips');
  const m = marker && marker.textContent.match(/^…older output trimmed \((\d+) blocks\)$/);
  check(ctx, !!m,
    `marker text matches "…older output trimmed (N blocks)" exactly (got: ${marker && JSON.stringify(marker.textContent)})`);
  const trimmedCount = m ? parseInt(m[1], 10) : -1;

  const survivors = [...body.querySelectorAll('.block:not(.block-elision)')];
  check(ctx, trimmedCount === 195 && survivors.length === 5,
    `195 elided / 5 survivors (block-count cap) (got trimmed=${trimmedCount}, survivors=${survivors.length})`);
  check(ctx, trimmedCount + survivors.length === N,
    `elided (${trimmedCount}) + survivors (${survivors.length}) accounts for every appended block (${N})`);
  check(ctx, body.firstElementChild === marker,
    'elision marker sits at the OLDEST position (first child) — newest output stays visible');

  const newestIdx = N - 1;   // 199
  const lastSurvivorEl = survivors[survivors.length - 1];
  check(ctx, lastSurvivorEl.textContent === `. display ${newestIdx}`,
    `the newest block (display ${newestIdx}) is the last DOM child, content intact`);

  // Byte-identity: render the SAME newest block into a completely fresh,
  // uncapped console (memoryBudgetMb=8192, the slider max — this single
  // append can never approach that cap) and diff outerHTML. Trimming must
  // not alter surviving-block content in any way, not even whitespace.
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  let freshBody = document.getElementById('console-body');
  initConsole(freshBody, document.getElementById('console-empty'), null, 8192);
  appendBlock(mk(newestIdx));
  check(ctx, freshBody.firstElementChild.outerHTML === lastSurvivorEl.outerHTML,
    'the surviving newest block is byte-identical (outerHTML) to the SAME block rendered with no cap pressure');

  // Also check an INTERIOR survivor (not just the last one) — "below the
  // cap" means all of it, not just the tail.
  const midK = Math.floor(survivors.length / 2);            // 2
  const midSurvivorEl = survivors[midK];
  const midIdx = newestIdx - (survivors.length - 1) + midK; // 197
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  freshBody = document.getElementById('console-body');
  initConsole(freshBody, document.getElementById('console-empty'), null, 8192);
  appendBlock(mk(midIdx));
  check(ctx, freshBody.firstElementChild.outerHTML === midSurvivorEl.outerHTML,
    `an interior surviving block (display ${midIdx}) is also byte-identical (outerHTML) to its uncapped render`);

  document.body.innerHTML = '';
  setMemoryBudgetMb(DEFAULT_MEMORY_BUDGET_MB);   // restore for later suites
});

suite('P7: console cap (byte-bound) trims on total size even when block count alone would not trip', (ctx) => {
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  const body = document.getElementById('console-body');
  initConsole(body, document.getElementById('console-empty'), null);
  clearConsole();

  // mb=50 -> byteBudget=524288 B (512 KB), blockCount=1200. 400 blocks of
  // ~2 KB of JSON each: 400 < blockCount (count alone would never trip), but
  // 400 * ~2 KB ~= 800 KB > byteBudget — so any trimming here is proof the
  // BYTE dimension is an independently functioning constraint, not the
  // block-count one riding along.
  setMemoryBudgetMb(50);
  const N = 400;
  const mk = (i) => ({ type: 'echo', text: 'x'.repeat(2000) + i });
  for (let i = 0; i < N; i++) appendBlock(mk(i));

  const marker = body.querySelector('.block-elision');
  check(ctx, marker != null, 'elision marker rendered (byte budget tripped, not block count)');
  const m = marker && marker.textContent.match(/^…older output trimmed \((\d+) blocks\)$/);
  const trimmedCount = m ? parseInt(m[1], 10) : -1;
  const survivors = [...body.querySelectorAll('.block:not(.block-elision)')];

  check(ctx, trimmedCount === 142 && survivors.length === 258,
    `142 elided / 258 survivors (byte cap, well under the 1200 block-count cap) (got trimmed=${trimmedCount}, survivors=${survivors.length})`);
  check(ctx, trimmedCount + survivors.length === N,
    `elided (${trimmedCount}) + survivors (${survivors.length}) accounts for every appended block (${N})`);
  check(ctx, survivors.length < 1200,
    'survivor count is well under the 1200 block-count cap — bytes bound this trim, not block count');

  document.body.innerHTML = '';
  setMemoryBudgetMb(DEFAULT_MEMORY_BUDGET_MB);   // restore for later suites
});

// ════════════════════════════════════════════════════════════════════════════
// A3-01 regression guard (WS-F2 mission verification #2) — .g-point/.g-line
// must resolve to a real, non-black, non-none color under the SHIPPED DEFAULT
// (Boring mode). The original bug: --graph-accent-1/-2 were only defined
// inside [data-mode="destijl"], so in Boring (default, no override) `var()`
// failed to resolve and points/lines fell back to initial (solid black /
// stroke:none). WS-C1's fix hoisted the tokens to :root; this suite locks it.
//
// jsdom does not substitute var() into computed style (it returns the raw
// "var(--name)" text for properties like SVG fill/stroke rather than a real
// browser's resolved color) — so we resolve the referenced custom property
// ourselves against :root's computed style, the same value a real browser
// would substitute in.
// ════════════════════════════════════════════════════════════════════════════
suite('A3-01 regression guard: .g-point/.g-line resolve to a real color in Boring mode', (ctx) => {
  const NSVG = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NSVG, 'svg');
  const point = document.createElementNS(NSVG, 'circle');
  point.setAttribute('class', 'g-point');
  const line = document.createElementNS(NSVG, 'path');
  line.setAttribute('class', 'g-line');
  svg.appendChild(point);
  svg.appendChild(line);
  // Must be attached under <html> for CSS custom-property inheritance from
  // :root to actually reach these elements (disconnected nodes don't inherit).
  document.body.appendChild(svg);

  const rootCS = getComputedStyle(document.documentElement);
  function resolveVarRef(raw) {
    const m = String(raw).match(/^var\((--[\w-]+)\)/);
    return m ? rootCS.getPropertyValue(m[1]).trim() : raw;
  }
  const isBlackOrNone = (v) => !v || v === 'none' ||
    /^(#000+$|black$|rgba?\(\s*0,\s*0,\s*0\b)/i.test(v.trim());

  const rawFill   = getComputedStyle(point).fill;
  const rawStroke = getComputedStyle(line).stroke;
  const fill   = resolveVarRef(rawFill);
  const stroke = resolveVarRef(rawStroke);

  check(ctx, !isBlackOrNone(fill),
    `.g-point fill resolves to a real color in Boring mode (computed "${rawFill}" → "${fill}")`);
  check(ctx, !isBlackOrNone(stroke),
    `.g-line stroke resolves to a real color in Boring mode (computed "${rawStroke}" → "${stroke}")`);

  document.body.removeChild(svg);
});

// ════════════════════════════════════════════════════════════════════════════
// Paste auto-run preference (WS-F1 follow-up to design decision 4)
//   Integration-drives the REAL app.js: init() + the actual #cmd-input paste
//   listener, inside jsdom, against a RECORDING fake window.pietNative bridge
//   (so "do_string was/wasn't called" is asserted at the transport seam, not
//   inferred). Async orchestration runs here at module top level (the suite()
//   harness is synchronous); the suite below asserts on the collected
//   observations.
//   Legs (mission DoD):
//     - default (key absent) = OFF → editor opens with content, NOTHING executes
//     - checkbox click → localStorage 'piet-paste-autorun' round-trips '1'/'0'
//     - ON → do_string called with the pasted source; editor untouched
//     - state.busy still guards the ON path (concurrent 2nd paste swallowed)
//     - persisted '1' survives a re-init (checkbox reflects the store at boot)
// ════════════════════════════════════════════════════════════════════════════
const pasteObs = await (async () => {
  const obs = {};
  const bridgeCalls = [];
  // Recording fake bridge: same {request(key, body) -> Promise} surface as
  // shell.cpp's installBridge(). Its presence flips api.js to the native
  // transport (hasNativeBridge wins over the http://localhost jsdom origin).
  dom.window.pietNative = {
    request: async (key, body) => {
      bridgeCalls.push({ key, body });
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'do_string':    return { blocks: [{ type: 'echo', text: '.  do (pasted)' }] };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        default:             return {};
      }
    },
  };
  const doStringCalls = () => bridgeCalls.filter((c) => c.key === 'do_string');

  // Minimal app DOM: only ids app.js's paste path + init() actually touch
  // (every other getElementById in init() is null-guarded).
  function buildAppDom() {
    document.body.innerHTML = `
      <div id="pane-console">
        <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
        <div id="cmd-bar">
          <input id="cmd-input" type="text">
          <button id="btn-run" type="button">Run</button>
        </div>
        <div id="doedit-overlay" class="console-overlay">
          <div class="doedit-bar">
            <span class="doedit-title" id="doedit-title">Do-file Editor</span>
            <label id="paste-autorun-label"><input type="checkbox" id="paste-autorun-toggle"> Run pasted blocks immediately</label>
          </div>
          <textarea id="doedit-text"></textarea>
        </div>
      </div>
      <div id="var-list-wrap"></div>
      <ul id="hist-list"></ul>
      <span class="kernel-dot" id="kernel-dot"></span>`;
  }
  function dispatchPaste(text) {
    const input = document.getElementById('cmd-input');
    const ev = new dom.window.Event('paste', { bubbles: true, cancelable: true });
    ev.clipboardData = { getData: () => text };
    input.dispatchEvent(ev);
  }
  const settle  = () => new Promise((r) => setTimeout(r, 0));
  const toggle  = () => document.getElementById('paste-autorun-toggle');
  const overlay = () => document.getElementById('doedit-overlay');
  const editor  = () => document.getElementById('doedit-text');

  // ── Boot with the key ABSENT → shipped default (OFF). ──
  localStorage.removeItem('piet-paste-autorun');
  buildAppDom();
  const { init } = await import(JS('app.js'));
  await init();
  obs.defaultChecked = toggle().checked;

  // ── OFF leg: paste loads + opens the editor; nothing executes. ──
  const P1 = 'summarize price\nregress price mpg';
  dispatchPaste(P1);
  await settle();
  obs.offEditorOpen    = overlay().classList.contains('open');
  obs.offEditorText    = editor().value;
  obs.offDoStringCount = doStringCalls().length;

  // ── Checkbox ON → localStorage write. ──
  toggle().click();                        // jsdom fires change on checkbox click
  obs.lsAfterCheck = localStorage.getItem('piet-paste-autorun');
  overlay().classList.remove('open');      // reset editor state to isolate the ON leg
  editor().value = '';

  // ── ON leg + busy guard: P2 then P3 in the SAME tick — runPastedBlock's
  //    state.busy guard must swallow P3. ──
  const P2 = 'gen x = 1\nsummarize x';
  dispatchPaste(P2);
  obs.inputDisabledDuringRun = document.getElementById('cmd-input').disabled;
  dispatchPaste('list x\nlist x');         // concurrent paste while busy
  await settle(); await settle();
  obs.onDoStringCount    = doStringCalls().length;
  obs.onSource           = doStringCalls()[0]?.body?.source;
  obs.onEditorOpen       = overlay().classList.contains('open');
  obs.onEditorText       = editor().value;
  obs.onEcho             = document.getElementById('console-body').textContent.includes('do (pasted)');
  obs.onHistoryEntry     = document.getElementById('hist-list').textContent.includes('do (pasted)');
  obs.inputDisabledAfter = document.getElementById('cmd-input').disabled;

  // ── Negative control: after the run settles (busy released) a paste runs again. ──
  dispatchPaste('display 1\ndisplay 2');
  await settle(); await settle();
  obs.afterGuardCount = doStringCalls().length;

  // ── Checkbox OFF → '0' persisted; behavior back to editor-load. ──
  toggle().click();
  obs.lsAfterUncheck = localStorage.getItem('piet-paste-autorun');
  overlay().classList.remove('open');
  editor().value = '';
  dispatchPaste('tab foreign\ntab rep78');
  await settle();
  obs.zeroEditorOpen    = overlay().classList.contains('open');
  obs.zeroDoStringCount = doStringCalls().length;

  // ── Persistence across a "restart": seed '1', rebuild DOM, re-init. ──
  localStorage.setItem('piet-paste-autorun', '1');
  buildAppDom();
  await init();
  obs.rebootChecked = toggle().checked;
  dispatchPaste('use auto\nsummarize');
  await settle(); await settle();
  obs.rebootDoStringCount = doStringCalls().length;
  obs.rebootEditorOpen    = overlay().classList.contains('open');

  // Cleanup so later suites see a pristine environment.
  localStorage.removeItem('piet-paste-autorun');
  delete dom.window.pietNative;
  document.body.innerHTML = '';
  return obs;
})();

