// BS-028 companion (BETA C2+C3, frontend lane): dispatcher.cpp:2863-2886 records
// `"obs": true` on `pwcorr ..., obs` blocks (nobs[i][j] already flowed on every
// pairwise corr block beforehand) but left the NOTE that console.js had no code
// path reading it. Fixtures are REAL dispatcher output — piet_native --do on
// sysuse fatalities (pwcorr income beertax spirits[, obs]) — see
// piet/fixtures/dom/{pwcorr_obs,pwcorr_noobs}_estimation.json. Expected layout
// (coef row, then per-pair N row, then blank spacer) was verified against a
// live `StataBE -b do` run of the identical command on the same data.
suite('BS-028: pwcorr,obs renders the per-pair N beneath each coefficient (real dispatcher fixture)', (ctx) => {
  const obsBlock   = loadFix('dom/pwcorr_obs_estimation.json');
  const noObsBlock = loadFix('dom/pwcorr_noobs_estimation.json');
  check(ctx, obsBlock.estimator === 'corr' && obsBlock.method === 'pwcorr',
    `dom/pwcorr_obs_estimation.json carries estimator="corr", method="pwcorr" (got "${obsBlock.estimator}"/"${obsBlock.method}")`);
  check(ctx, obsBlock.obs === true && Array.isArray(obsBlock.nobs),
    `dom/pwcorr_obs_estimation.json carries obs=true and a nobs matrix`);
  check(ctx, noObsBlock.obs !== true && Array.isArray(noObsBlock.nobs),
    `dom/pwcorr_noobs_estimation.json (control) carries obs!==true while STILL carrying a nobs matrix ` +
    `(proves the renderer gates on obs===true, not merely nobs's presence)`);

  const obsText   = renderEstimationToDom(obsBlock);
  const noObsText = renderEstimationToDom(noObsBlock);

  const names = obsBlock.variables;
  // Every lower-triangular r(i,j) value (including the diagonal 1.0000) must
  // reach the rendered DOM — same Number().toFixed(4) formatting formatCorrelate
  // itself uses, so this is not a hand-typed literal drifting out of sync.
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j <= i; j++) {
      const expected = Number(obsBlock.r[i][j]).toFixed(4);
      check(ctx, obsText.includes(expected),
        `pwcorr,obs: DOM contains coefficient r(${names[i]},${names[j]})=${expected}`);
    }
  }
  // Every per-pair N (including the diagonal — a pair's own obs count is
  // well-defined, unlike the sig row's blank diagonal) must reach the DOM.
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j <= i; j++) {
      const expected = String(obsBlock.nobs[i][j]);
      check(ctx, obsText.includes(expected),
        `pwcorr,obs: DOM contains per-pair N(${names[i]},${names[j]})=${expected}`);
    }
  }
  check(ctx, obsText.split('\n').length > noObsText.split('\n').length,
    `pwcorr,obs: obs-rendering emits more lines than the plain (no-obs) rendering of the same vars`);

  // Control: the SAME data rendered WITHOUT obs (block.obs !== true, even though
  // its own nobs matrix — real dispatcher output — still carries the identical
  // N values) must show NO per-pair N lines at all.
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j <= i; j++) {
      const nStr = String(noObsBlock.nobs[i][j]);
      check(ctx, !noObsText.includes(nStr),
        `pwcorr (no obs): DOM does NOT contain N(${names[i]},${names[j]})=${nStr} (obs!==true must suppress the row)`);
    }
  }
});

