suite('BS-049: kdensity kernel/grid fix — corrected Epanechnikov values still render (real oracle fixture)', (ctx) => {
  const block = loadFix('dom/kdensity_graph.json');
  check(ctx, block.kind === 'line', `kdensity income emits kind="line" (got "${block.kind}")`);
  check(ctx, block.subkind === 'kdensity', `block carries subkind="kdensity"`);
  check(ctx, block.kernel === 'epanechnikov', `default kernel is epanechnikov (BS-049), got "${block.kernel}"`);

  // Pin two real oracle-verified data points (grid endpoints) — a regression
  // net for BS-049's grid-range fix (was padded 3*bwidth; corrected to exactly
  // 1*bwidth beyond xmin/xmax) and its Epanechnikov kernel formula.
  const pts = block.points;
  check(ctx, pts.length === 512, `kdensity default n_grid=512 (got ${pts.length})`);
  const [x0, y0] = pts[0];
  const [xN, yN] = pts[pts.length - 1];
  check(ctx, Math.abs(x0 - block.x_min) < 1e-9 && Math.abs(xN - block.x_max) < 1e-9,
    `grid's first/last x exactly match block.x_min/x_max (BS-049 grid-range fix: xmin-bwidth .. xmax+bwidth)`);
  check(ctx, Math.abs(y0 - 4.97917374744656e-06) < 1e-12,
    `first grid point's density matches the oracle-pinned Epanechnikov value (got ${y0})`);
  check(ctx, Math.abs(yN - 1.2606142208528645e-06) < 1e-12,
    `last grid point's density matches the oracle-pinned Epanechnikov value (got ${yN})`);

  const el = renderGraph(block);
  const svg = el.querySelector('svg');
  check(ctx, !!svg, 'renderGraph(kdensity line block) produces an <svg>');
  const path = svg.querySelector('path.g-line');
  check(ctx, !!path, 'kdensity renders through the existing renderLine path (a single <path class="g-line">)');
  const dAttr = path.getAttribute('d') || '';
  const segCount = (dAttr.match(/[ML]/g) || []).length;
  check(ctx, segCount === 512, `rendered path carries exactly 512 M/L path commands, one per grid point (got ${segCount})`);
});

