// ════════════════════════════════════════════════════════════════════════════
// D9 (BETA Phase F) — request-dialog overlay (native _request()).
//   Integration-drives the REAL app.js: init() wires initPietEventsBridge()
//   against a fake `window.pietEvents` EventTarget (mirrors the native
//   shell's push channel — see app.js's initPietEventsBridge() doc comment)
//   and a RECORDING fake `window.pietNative` bridge, so both halves of the
//   wire contract are asserted at the transport seam:
//     push:   {kind:"request_dialog", requestId, prompt, macroName} ->
//             CustomEvent('piet-event', {detail}) on window.pietEvents
//     answer: POST /api/request/answer -> routing key "request.answer",
//             body {requestId, value}
//   Three legs (mission DoD):
//     - a request_dialog push opens #request-overlay with the prompt/
//       macroName text, Submit posts {requestId, value} to "request.answer",
//       and the overlay closes afterward
//     - Escape does NOT dismiss the overlay while a request is pending (the
//       abandoned-modal edge-case decision — see app.js's openRequestDialog()
//       doc comment)
//     - "Cancel run" calls the EXISTING run_cancel route (not request.answer)
//       and also closes the overlay
// ════════════════════════════════════════════════════════════════════════════
const requestDialogObs = await (async () => {
  const obs = {};
  const bridgeCalls = [];
  dom.window.pietNative = {
    request: async (key, body) => {
      bridgeCalls.push({ key, body });
      switch (key) {
        case 'varlist':        return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':        return { history: [] };
        case 'version':        return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'run_progress':   return { running: true, current_line: 1, total_lines: 3, current_cmd: '', elapsed_ms: 0 };
        case 'run_cancel':     return { cancelled: true };
        case 'request.answer': return { ok: true };
        case 'settings.set':   return { ok: true, memory_budget_mb: body && body.memory_budget_mb };
        default:                return {};
      }
    },
  };
  // Fake native push channel — mirrors window.pietEvents (see app.js's
  // initPietEventsBridge()): a plain EventTarget dispatching 'piet-event'.
  dom.window.pietEvents = new dom.window.EventTarget();

  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar">
        <input id="cmd-input" type="text">
        <button id="btn-run" type="button">Run</button>
      </div>
      <div id="request-overlay" class="console-overlay">
        <div class="doedit-bar"><span class="doedit-title" id="request-title">Do-file is waiting for input</span></div>
        <div class="request-body">
          <p class="request-hint" id="request-macro"></p>
          <p class="request-prompt" id="request-prompt"></p>
          <form id="request-form" class="request-form">
            <input id="request-input" type="text" required>
            <div class="request-actions">
              <button type="button" id="request-cancel-run">Cancel run</button>
              <button type="submit" id="request-submit">Submit</button>
            </div>
          </form>
          <p id="request-status"></p>
        </div>
      </div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span class="kernel-dot" id="kernel-dot"></span>`;

  const { init } = await import(JS('app.js'));
  await init();
  const settle = () => new Promise((r) => setTimeout(r, 0));

  const overlay   = () => document.getElementById('request-overlay');
  const promptEl  = () => document.getElementById('request-prompt');
  const macroEl   = () => document.getElementById('request-macro');
  const inputEl   = () => document.getElementById('request-input');
  const answerCalls = () => bridgeCalls.filter((c) => c.key === 'request.answer');
  const cancelCalls = () => bridgeCalls.filter((c) => c.key === 'run_cancel');

  function pushRequestDialog(detail) {
    dom.window.pietEvents.dispatchEvent(new dom.window.CustomEvent('piet-event', { detail }));
  }

  obs.closedBeforeAnyPush = !overlay().classList.contains('open');

  // ── Leg 1: push opens the overlay with prompt/macroName; Submit answers. ──
  pushRequestDialog({ kind: 'request_dialog', requestId: 'req-1', prompt: 'Enter a threshold:', macroName: 'mythreshold' });
  await settle();
  obs.openAfterPush   = overlay().classList.contains('open');
  obs.promptText      = promptEl().textContent;
  obs.macroTextHasName = macroEl().textContent.includes('mythreshold');

  // Existing RunProgress-shaped pushes (no "kind") must still be ignored by
  // the request-dialog branch and NOT interfere with the pending dialog.
  pushRequestDialog({ running: true, current_line: 2, total_lines: 3, current_cmd: 'regress', elapsed_ms: 500 });
  await settle();
  obs.stillOpenAfterProgressPush = overlay().classList.contains('open');

  // ── Leg 2: Escape must NOT dismiss it (abandoned-modal edge case). ──
  const escEvent = new dom.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true });
  inputEl().dispatchEvent(escEvent);
  obs.openAfterEscape = overlay().classList.contains('open');

  // ── Submit with an answer -> POST /api/request/answer, then closes. ──
  inputEl().value = '0.05';
  document.getElementById('request-form')
    .dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
  await settle();
  obs.answerCallCount = answerCalls().length;
  obs.answerBody      = answerCalls()[0]?.body;
  obs.closedAfterSubmit = !overlay().classList.contains('open');

  // ── Leg 3: a second push, dismissed via "Cancel run" instead of an answer. ──
  pushRequestDialog({ kind: 'request_dialog', requestId: 'req-2', prompt: 'Confirm?', macroName: '' });
  await settle();
  obs.macroTextDefaultsWhenEmpty = macroEl().textContent.length > 0 && !macroEl().textContent.includes('“');
  document.getElementById('request-cancel-run').click();
  await settle();
  obs.cancelCallCount     = cancelCalls().length;
  obs.answerCallCountAfterCancel = answerCalls().length;   // must still be 1 — cancel path never posts an answer
  obs.closedAfterCancel   = !overlay().classList.contains('open');

  // ── Defensive: a malformed push (kind present, requestId missing) must
  //    NOT open the overlay (openRequestDialog()'s early-return guard). ──
  pushRequestDialog({ kind: 'request_dialog', prompt: 'no id' });
  await settle();
  obs.stillClosedOnMissingId = !overlay().classList.contains('open');

  // ── Leg 4 (SPEC II-4, 2026-09-02): a fixed-choice push renders buttons; the
  //    text form hides; "raise" persists the suggested budget via settings.set
  //    and then answers by value; the overlay closes. ──
  const choicesPush = {
    kind: 'request_dialog', requestId: 'req-3', macroName: '_piet_preflight',
    prompt: 'merge would need about 6.1 GiB; the memory budget is 4096 MB.',
    choices: [{ value: 'proceed', label: 'Proceed anyway' },
              { value: 'raise', label: 'Raise the budget to 6272 MB and proceed' },
              { value: 'cancel', label: 'Cancel this command' }],
    suggest_budget_mb: 6272,
  };
  pushRequestDialog(choicesPush);
  await settle();
  const choiceBox = () => document.getElementById('request-choices');
  obs.choiceButtonCount = choiceBox() ? choiceBox().querySelectorAll('button').length : -1;
  obs.choiceLabels = choiceBox() ? [...choiceBox().querySelectorAll('button')].map((b) => b.textContent) : [];
  obs.formHiddenForChoices = document.getElementById('request-form').hidden === true;
  const raiseBtn = choiceBox() && [...choiceBox().querySelectorAll('button')].find((b) => b.dataset.value === 'raise');
  raiseBtn?.click();
  await settle(); await settle();
  const setCalls = bridgeCalls.filter((c) => c.key === 'settings.set');
  obs.raiseSettingsBody = setCalls[setCalls.length - 1]?.body;
  obs.raiseAnswerBody = answerCalls()[answerCalls().length - 1]?.body;
  obs.answerCountAfterRaise = answerCalls().length;   // Leg 1's one + this one = 2
  obs.closedAfterRaise = !overlay().classList.contains('open');
  obs.formRestoredAfterClose = document.getElementById('request-form').hidden === false;
  // A plain text push afterwards must show the text form again (choices cleared).
  pushRequestDialog({ kind: 'request_dialog', requestId: 'req-4', prompt: 'text again', macroName: 'm' });
  await settle();
  obs.textFormBackAfterChoices = document.getElementById('request-form').hidden === false
    && (!choiceBox() || choiceBox().hidden === true);
  document.getElementById('request-cancel-run').click();
  await settle();

  delete dom.window.pietNative;
  delete dom.window.pietEvents;
  document.body.innerHTML = '';
  return obs;
})();

suite('D9: request-dialog overlay — push opens it, Submit answers via /api/request/answer', (ctx) => {
  check(ctx, requestDialogObs.closedBeforeAnyPush === true,
    '#request-overlay starts closed (no .open class) before any push');
  check(ctx, requestDialogObs.openAfterPush === true,
    'a request_dialog push opens #request-overlay (.open)');
  check(ctx, requestDialogObs.promptText === 'Enter a threshold:',
    'the prompt text renders verbatim');
  check(ctx, requestDialogObs.macroTextHasName === true,
    'macroName is surfaced in the dialog (context for which macro is asking)');
  check(ctx, requestDialogObs.stillOpenAfterProgressPush === true,
    'a shape-based RunProgress push (no "kind") does not interfere with an already-open request dialog');
  check(ctx, requestDialogObs.answerCallCount === 1,
    'Submit posts exactly one request.answer call');
  check(ctx, requestDialogObs.answerBody && requestDialogObs.answerBody.requestId === 'req-1'
    && requestDialogObs.answerBody.value === '0.05',
    `request.answer body carries {requestId, value} exactly (got ${JSON.stringify(requestDialogObs.answerBody)})`);
  check(ctx, requestDialogObs.closedAfterSubmit === true,
    '#request-overlay closes after a successful submit');
});

suite('D9: request-dialog overlay — Escape does not dismiss it; Cancel run uses the existing run_cancel route', (ctx) => {
  check(ctx, requestDialogObs.openAfterEscape === true,
    'Escape does NOT close #request-overlay while a native request is pending (abandoned-modal decision)');
  check(ctx, requestDialogObs.macroTextDefaultsWhenEmpty === true,
    'an empty macroName still shows a "do-run is paused" hint (not blank)');
  check(ctx, requestDialogObs.cancelCallCount === 1,
    '"Cancel run" calls run_cancel exactly once');
  check(ctx, requestDialogObs.answerCallCountAfterCancel === 1,
    '"Cancel run" never posts to request.answer (still just the one Leg-1 submit)');
  check(ctx, requestDialogObs.closedAfterCancel === true,
    '#request-overlay closes after "Cancel run"');
  check(ctx, requestDialogObs.stillClosedOnMissingId === true,
    'a malformed push with no requestId does NOT open the overlay (defensive guard)');
});

// ════════════════════════════════════════════════════════════════════════════
suite('II-4: memory pre-flight — a choices push renders proceed/raise/cancel buttons; Raise sets the budget then answers by value', (ctx) => {
  check(ctx, requestDialogObs.choiceButtonCount === 3,
    `a request_dialog push with 3 choices renders 3 buttons (got ${requestDialogObs.choiceButtonCount})`);
  check(ctx, Array.isArray(requestDialogObs.choiceLabels) && requestDialogObs.choiceLabels[1] === 'Raise the budget to 6272 MB and proceed',
    'button labels come from the push verbatim');
  check(ctx, requestDialogObs.formHiddenForChoices === true,
    'the free-text form is hidden while choices are shown (no empty Submit to click)');
  check(ctx, requestDialogObs.raiseSettingsBody && requestDialogObs.raiseSettingsBody.memory_budget_mb === 6272,
    `"raise" persists the suggested budget through settings.set first (got ${JSON.stringify(requestDialogObs.raiseSettingsBody)})`);
  check(ctx, requestDialogObs.raiseAnswerBody && requestDialogObs.raiseAnswerBody.requestId === 'req-3'
    && requestDialogObs.raiseAnswerBody.value === 'raise',
    `...then answers {requestId:"req-3", value:"raise"} on the unchanged answer wire (got ${JSON.stringify(requestDialogObs.raiseAnswerBody)})`);
  check(ctx, requestDialogObs.answerCountAfterRaise === 2,
    'exactly one answer per choice click (Leg 1 + this = 2 request.answer calls)');
  check(ctx, requestDialogObs.closedAfterRaise === true,
    '#request-overlay closes after a choice is answered');
  check(ctx, requestDialogObs.formRestoredAfterClose === true && requestDialogObs.textFormBackAfterChoices === true,
    'a later free-text push shows the text form again (choices do not leak across pushes)');
});

// SPEC II-3 (2026-09-02): the data grid's cache depth and prefetch depth follow
// the memory budget. gridCapsForBudget() is the pure map app.js pushes the live
// setting through (setGridMemoryBudgetMb) beside console.js's cap.
const { gridCapsForBudget, setGridMemoryBudgetMb } = await import(JS('grid.js'));
suite('II-3: grid cache windows and prefetch depth follow the memory budget', (ctx) => {
  const c0 = gridCapsForBudget(0);
  check(ctx, c0.maxCache === 3 && c0.prefetch === 1, 'no budget -> the historical constants (3 windows, prefetch 1)');
  const c2048 = gridCapsForBudget(2048);
  check(ctx, c2048.maxCache === 8 && c2048.prefetch === 2, `2048 MB -> 8 windows, prefetch 2 (got ${JSON.stringify(c2048)})`);
  const c4096 = gridCapsForBudget(4096);
  check(ctx, c4096.maxCache === 16 && c4096.prefetch === 2, `4096 MB -> 16 windows (got ${JSON.stringify(c4096)})`);
  const c256 = gridCapsForBudget(256);
  check(ctx, c256.maxCache === 3 && c256.prefetch === 1, '256 MB (the slider minimum) -> the floor of 3, prefetch 1');
  const cBig = gridCapsForBudget(65536);
  check(ctx, cBig.maxCache === 32, 'the cache depth is capped at 32 windows however large the budget');
  check(ctx, gridCapsForBudget('junk').maxCache === 3, 'a non-numeric budget falls back to the constants');
  const live = setGridMemoryBudgetMb(8192);
  check(ctx, live.maxCache === 32 && live.prefetch === 2, 'setGridMemoryBudgetMb() returns the caps it put in force');
  check(ctx, c2048.maxCache < c4096.maxCache && c4096.maxCache <= cBig.maxCache, 'caps are monotone in the budget');
});

// P8 UI regression suites (find.js / varstats.js / theme tokens / C4 block-active).
// find.js and varstats.js aren't imported by the top-of-file module block above
// (only console.js/graph.js/util.js are) — pulled in here, right where they're
// first needed, rather than editing the shared import list every other suite
// in this file relies on.
// ════════════════════════════════════════════════════════════════════════════
const { initFind, openFind, closeFind, isFindOpen } = await import(JS('find.js'));
const { cacheSummarizeStats, getVarStats, clearVarStatsCache } = await import(JS('varstats.js'));

// ════════════════════════════════════════════════════════════════════════════
// B11/B12 (find.js) — ⌘F find bar: Results surface (find-only, in-place
// <mark class="find-hit">, byte-restored on close) + do-file editor surface
// (find + Replace All, B12 "선택한 것 다같이 바꾸기"). Real markup ids copied
// verbatim from index.html (find-bar-results/find-bar-doedit and children) so
// find.js's getElementById lookups in initFind() resolve exactly as they do
// in the shipped app.
// ════════════════════════════════════════════════════════════════════════════
suite('B11/B12: find.js — find-in-Results (mark/unwrap) + Replace All in the do-editor', (ctx) => {
  document.body.innerHTML = `
    <div id="find-bar-results" class="find-bar" data-surface="results" hidden>
      <input type="text" id="find-input-results" class="find-q" aria-label="Find in results"
             autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="Find">
      <span class="find-cnt" id="find-cnt-results">0/0</span>
      <button type="button" class="find-btn find-nav" id="find-prev-results" title="Previous match (Shift+Enter)">&lsaquo;</button>
      <button type="button" class="find-btn find-nav" id="find-next-results" title="Next match (Enter)">&rsaquo;</button>
      <button type="button" class="find-btn find-aa" id="find-case-results" title="Match case" aria-pressed="false">Aa</button>
      <button type="button" class="find-btn find-close" id="find-close-results" title="Close (Esc)">&times;</button>
    </div>
    <div id="console-wrap">
      <div id="console-empty" aria-hidden="true"></div>
      <div id="console-body" role="log" aria-live="polite" aria-label="Command output">
        <div class="block block-estimation"><pre>Coefficient beta estimate: 0.42</pre></div>
        <div class="block block-echo">. display beta</div>
        <div class="block block-estimation"><pre>beta again here</pre></div>
      </div>
    </div>
    <div id="doedit-overlay" class="console-overlay">
      <div id="find-bar-doedit" class="find-bar" data-surface="doedit" hidden>
        <input type="text" id="find-input-doedit" class="find-q" aria-label="Find in do-file"
               autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="Find">
        <span class="find-cnt" id="find-cnt-doedit">0/0</span>
        <button type="button" class="find-btn find-nav" id="find-prev-doedit" title="Previous match (Shift+Enter)">&lsaquo;</button>
        <button type="button" class="find-btn find-nav" id="find-next-doedit" title="Next match (Enter)">&rsaquo;</button>
        <button type="button" class="find-btn find-aa" id="find-case-doedit" title="Match case" aria-pressed="false">Aa</button>
        <input type="text" id="find-replace-doedit" class="find-rep" aria-label="Replace with"
               autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="Replace">
        <button type="button" class="find-btn find-go" id="find-replace-one-doedit">Replace</button>
        <button type="button" class="find-btn find-go" id="find-replace-all-doedit">Replace all</button>
        <button type="button" class="find-btn find-close" id="find-close-doedit" title="Close (Esc)">&times;</button>
      </div>
      <textarea id="doedit-text" class="doedit-text" spellcheck="false" autocomplete="off"
                autocapitalize="off" autocorrect="off"></textarea>
    </div>`;
  initFind();

  // ── Results surface: find-only, marks + count, byte-restore on close. ──
  check(ctx, isFindOpen() === false, 'isFindOpen() is false before any openFind() call');

  openFind();   // #doedit-overlay has no .open class yet -> _activeSurface() picks 'results'
  const resBar = document.getElementById('find-bar-results');
  check(ctx, isFindOpen() === true && resBar.classList.contains('open') && resBar.hidden === false,
    'openFind() targets the Results surface: isFindOpen() true, #find-bar-results opens (.open, not hidden)');

  const resQ = document.getElementById('find-input-results');
  resQ.value = 'beta';
  resQ.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));

  const hits = [...document.querySelectorAll('#console-body mark.find-hit')];
  check(ctx, hits.length === 3, `"beta" query wraps all 3 occurrences in mark.find-hit (got ${hits.length})`);
  const resCnt = document.getElementById('find-cnt-results');
  check(ctx, resCnt.textContent.endsWith('/3'),
    `#find-cnt-results reflects the 3-match count (got ${JSON.stringify(resCnt.textContent)})`);

  closeFind();
  check(ctx, isFindOpen() === false, 'closeFind() clears isFindOpen()');
  check(ctx, document.querySelectorAll('#console-body mark.find-hit').length === 0,
    'closeFind() unwraps every mark.find-hit — no <mark> survives close() (results log stays immutable)');
  check(ctx, resBar.classList.contains('open') === false && resBar.hidden === true,
    '#find-bar-results is hidden again after closeFind()');
  check(ctx, document.getElementById('console-body').textContent.includes('beta'),
    'the underlying result text itself survives the unwrap byte-for-byte');

  // ── Do-editor surface: find + Replace All on the textarea value. ──
  document.getElementById('doedit-overlay').classList.add('open');
  const doTA = document.getElementById('doedit-text');
  doTA.value = 'foo TOKEN middle TOKEN after TOKEN end';

  openFind();   // #doedit-overlay.open now -> _activeSurface() picks 'doedit'
  const doBar = document.getElementById('find-bar-doedit');
  check(ctx, isFindOpen() === true && doBar.classList.contains('open') && doBar.hidden === false,
    'openFind() while #doedit-overlay is .open targets the do-editor surface (#find-bar-doedit opens)');

  const doQ = document.getElementById('find-input-doedit');
  doQ.value = 'TOKEN';
  doQ.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));
  const doCnt = document.getElementById('find-cnt-doedit');
  check(ctx, doCnt.textContent.endsWith('/3'),
    `#find-cnt-doedit reflects the 3 "TOKEN" matches found in the textarea (got ${JSON.stringify(doCnt.textContent)})`);

  document.getElementById('find-replace-doedit').value = 'REPL';
  document.getElementById('find-replace-all-doedit').click();   // -> _replaceAll()

  check(ctx, doTA.value === 'foo REPL middle REPL after REPL end',
    `Replace All replaces every "TOKEN" occurrence in the do-editor textarea (got ${JSON.stringify(doTA.value)})`);
  check(ctx, !doTA.value.includes('TOKEN'), 'no "TOKEN" occurrence survives Replace All');
  check(ctx, doCnt.textContent === '0/0',
    `#find-cnt-doedit re-searches after Replace All and finds zero remaining matches (got ${JSON.stringify(doCnt.textContent)})`);

  closeFind();
  check(ctx, isFindOpen() === false, 'closeFind() closes the do-editor find bar too');
  check(ctx, doBar.classList.contains('open') === false && doBar.hidden === true,
    '#find-bar-doedit is hidden again after closeFind()');

  document.body.innerHTML = '';
});

// ════════════════════════════════════════════════════════════════════════════
// B14(a) (varstats.js) — passive per-variable summarize cache. console.js's
// appendBlock() calls cacheSummarizeStats(block) whenever it renders a
// `summarize` block (console.js:161-164); panels.js's detail card later reads
// it back via getVarStats(). No `summarize` dom fixture exists in
// fixtures/dom/ (checked: coefplot/kdensity/logit/margins/pwcorr/reghdfe/
// scatter/tabstat/twoway only) — this block is hand-built to the SAME shape
// formatSummarize() reads (console.js:1164-1183: block.stats[varname] =
// {N, mean, sd, min, max}), values mirroring sysuse auto's well-known mpg/
// weight summarize output.
// ════════════════════════════════════════════════════════════════════════════
suite('B14(a): varstats.js — passive summarize cache (cacheSummarizeStats / getVarStats / clearVarStatsCache)', (ctx) => {
  clearVarStatsCache();
  check(ctx, getVarStats('mpg') == null, 'getVarStats() returns null before any summarize block is cached');

  const block = {
    type: 'summarize',
    stats: {
      mpg:    { N: 74, mean: 21.2973,  sd: 5.785503, min: 12,   max: 41 },
      weight: { N: 74, mean: 3019.459, sd: 777.1936, min: 1760, max: 4840 },
    },
  };
  cacheSummarizeStats(block);

  const mpg = getVarStats('mpg');
  check(ctx, mpg != null && mpg.N === 74 && mpg.mean === 21.2973 && mpg.sd === 5.785503
    && mpg.min === 12 && mpg.max === 41,
    `getVarStats('mpg') returns the cached stats verbatim (got ${JSON.stringify(mpg)})`);

  const weight = getVarStats('weight');
  check(ctx, weight != null && weight.N === 74 && weight.mean === 3019.459 && weight.min === 1760 && weight.max === 4840,
    `getVarStats('weight') returns its OWN cached stats independently of 'mpg' (got ${JSON.stringify(weight)})`);

  check(ctx, getVarStats('never_summarized') == null,
    'a variable that was never part of any cached summarize block stays uncached (null)');

  clearVarStatsCache();
  check(ctx, getVarStats('mpg') == null && getVarStats('weight') == null,
    'clearVarStatsCache() empties the cache for every previously-cached variable');
});

// ════════════════════════════════════════════════════════════════════════════
// P8-S8 theme tokens — phosphor green (--graph-line-1, piet.css §15b) scoped
// to [data-theme="dark"][data-mode="destijl"] ONLY. Regression class this
// guards: piet.css §15's own comment documents that --accent-green/
// --primary-blue/--focus-ring/--glow-btn-run were once repointed to green
// UNCONDITIONALLY inside the single-attribute [data-theme="dark"] block,
// which bled the Pip-Boy phosphor accent into Boring-Dark; the fix moved
// every such repoint into the two-attribute compound selector so Boring-Dark
// (§15) stays neutral. jsdom does not substitute var() chains into computed
// style (same caveat as the "A3-01 regression guard" suite above) — resolve
// one level of var(--name) manually against :root's own cascaded custom
// properties, the same value a real browser would substitute in.
// ════════════════════════════════════════════════════════════════════════════
suite('P8-S8: theme tokens — phosphor green (--graph-line-1) never leaks into Boring-Dark', (ctx) => {
  const PHOSPHOR_GREEN = '#7DE59B';   // piet.css §15b literal: [data-theme="dark"][data-mode="destijl"]
  const html = document.documentElement;

  function resolveToken(name) {
    const rootCS = getComputedStyle(html);
    const raw = rootCS.getPropertyValue(name).trim();
    const m = raw.match(/^var\((--[\w-]+)\)/);
    return m ? rootCS.getPropertyValue(m[1]).trim() : raw;
  }

  // (a) destijl x dark (Pip-Boy) -> the phosphor green, directly.
  html.setAttribute('data-mode', 'destijl');
  html.setAttribute('data-theme', 'dark');
  const pipBoy = resolveToken('--graph-line-1');
  check(ctx, pipBoy === PHOSPHOR_GREEN,
    `destijl×dark resolves --graph-line-1 to the phosphor green ${PHOSPHOR_GREEN} (got ${JSON.stringify(pipBoy)})`);

  // (b) boring x dark (Boring-Dark) -> must NOT be the phosphor green (the leak this guards).
  html.setAttribute('data-mode', 'boring');
  html.setAttribute('data-theme', 'dark');
  const boringDark = resolveToken('--graph-line-1');
  check(ctx, boringDark !== PHOSPHOR_GREEN,
    `boring×dark does NOT resolve --graph-line-1 to phosphor green (got ${JSON.stringify(boringDark)}) — Boring-Dark must stay neutral`);
  check(ctx, boringDark === '#5b9bd5',
    `boring×dark's --graph-line-1 resolves through --graph-accent-1 to its own neutral dark-mode blue (piet.css §15, got ${JSON.stringify(boringDark)})`);

  // (c) boring x light (shipped default) -> the base :root neutral value.
  html.setAttribute('data-mode', 'boring');
  html.removeAttribute('data-theme');
  const boringLight = resolveToken('--graph-line-1');
  check(ctx, boringLight === '#1850a8',
    `boring×light (default) --graph-line-1 resolves to the base :root value (piet.css line 50/62, got ${JSON.stringify(boringLight)})`);

  // Reset documentElement to the harness's shipped-default state (line 79's
  // boot-time setAttribute) so no suite after this one sees a different
  // data-mode/data-theme than it was written against.
  html.setAttribute('data-mode', 'boring');
  html.removeAttribute('data-theme');
});

// ════════════════════════════════════════════════════════════════════════════
// C4 (P8-S9) — live-coding single anchor invariant. console.js's appendBlock()
// (console.js:181-190) hands .block-active to the newest 'estimation' block
// only, stripping it from whichever block held it before; every other block
// type (echo/display/summarize/etc.) is not a "result" in the pointing-target
// sense and must never acquire it.
// ════════════════════════════════════════════════════════════════════════════
suite('C4 (P8-S9): .block-active — single live-anchor invariant across estimation blocks', (ctx) => {
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  const body = document.getElementById('console-body');
  initConsole(body, document.getElementById('console-empty'), null);
  clearConsole();

  const est = loadFix('dom/logit_estimation.json');   // real dispatcher fixture, type:'estimation'

  appendBlock(est);
  const firstEl = body.querySelector('.block-estimation');
  check(ctx, firstEl != null && firstEl.classList.contains('block-active'),
    'the first estimation block takes .block-active on append');
  check(ctx, body.querySelectorAll('.block-active').length === 1,
    'exactly one .block-active element exists after the first estimation block');

  // A non-estimation block appended in between must NOT take .block-active —
  // C4 is scoped to 'estimation' only (console.js:186 `if (block.type === 'estimation')`).
  appendBlock({ type: 'echo', text: 'summarize mpg' });
  check(ctx, body.querySelectorAll('.block-active').length === 1,
    'an interleaved echo block does not take .block-active (still exactly one)');
  check(ctx, firstEl.classList.contains('block-active'),
    'the first estimation block still holds .block-active after the echo block');

  appendBlock(est);
  const estimationEls = [...body.querySelectorAll('.block-estimation')];
  check(ctx, estimationEls.length === 2, 'two estimation blocks are now in the DOM');
  const secondEl = estimationEls[1];
  check(ctx, body.querySelectorAll('.block-active').length === 1,
    'exactly one .block-active element after the second estimation block (an eviction, not an addition)');
  check(ctx, secondEl.classList.contains('block-active') && !firstEl.classList.contains('block-active'),
    'the SECOND (latest) estimation block now holds .block-active; the first lost it');

  clearConsole();
  document.body.innerHTML = '';
});

