// ── BUG-114 — syncThemeButtons(): single owner for BOTH toggle labels ──────────
// Boots app.js against the four mode×theme combinations (set on <html> BEFORE
// init(), so this pins the "one early resync" boot guarantee itself, not just
// the click-driven paths) plus the cross-update fix: clicking #mode-toggle
// must ALSO refresh #theme-toggle's label in the same call.
const bug114Obs = await (async () => {
  const obs = {};
  function buildDom() {
    document.body.innerHTML = `
      <button class="toolbar-mode-btn" id="mode-toggle" aria-label="Toggle style mode">x</button>
      <button id="theme-toggle" aria-label="Toggle dark mode">x</button>
      <div id="pane-console">
        <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
        <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      </div>
      <div id="var-list-wrap"></div>
      <ul id="hist-list"></ul>
      <span id="status-file">(no data)</span><span id="status-dims"></span>
      <span class="kernel-dot" id="kernel-dot"></span>`;
  }
  const modeBtn  = () => document.getElementById('mode-toggle');
  const themeBtn = () => document.getElementById('theme-toggle');
  const html = document.documentElement;
  const { init } = await import(JS('app.js'));

  // boring + light
  html.dataset.mode = 'boring'; delete html.dataset.theme;
  buildDom(); await init();
  obs.boringLight = { mode: modeBtn().textContent, theme: themeBtn().textContent };

  // boring + dark
  html.dataset.mode = 'boring'; html.dataset.theme = 'dark';
  buildDom(); await init();
  obs.boringDark = { mode: modeBtn().textContent, theme: themeBtn().textContent };

  // destijl + light
  html.dataset.mode = 'destijl'; delete html.dataset.theme;
  buildDom(); await init();
  obs.destijlLight = { mode: modeBtn().textContent, theme: themeBtn().textContent };

  // destijl + dark
  html.dataset.mode = 'destijl'; html.dataset.theme = 'dark';
  buildDom(); await init();
  obs.destijlDark = { mode: modeBtn().textContent, theme: themeBtn().textContent };

  // Cross-update: from boring+light, clicking #mode-toggle must update BOTH labels.
  html.dataset.mode = 'boring'; delete html.dataset.theme;
  buildDom(); await init();
  obs.beforeModeClick = { mode: modeBtn().textContent, theme: themeBtn().textContent };
  modeBtn().click();
  obs.afterModeClick = { mode: modeBtn().textContent, theme: themeBtn().textContent };

  // Restore the harness's shipped-default document state.
  html.setAttribute('data-mode', 'boring');
  html.removeAttribute('data-theme');
  localStorage.removeItem('piet-mode');
  document.body.innerHTML = '';
  return obs;
})();

// B21-5 (User re-ruling, 07-16 evening): syncThemeButtons() no longer names
// the DESTINATION on #theme-toggle — it names the CURRENT theme ("지금이랑
// 반대로... 더 직관적" — the old destination-naming read backwards from what
// was on screen). Boring mode flips too, for the same one-button/one-
// convention consistency (see app.js's updated doc comment). #mode-toggle is
// UNCHANGED — it still names the action, not a state — so its expected
// values below are untouched; only every `.theme` expectation is
// re-expressed to the new truth. The CROSS-UPDATE assertion itself is kept
// (not weakened): clicking #mode-toggle still must flip #theme-toggle's text
// in the same call — mode flips boring→destijl while the underlying THEME
// stays light throughout, so under current-state naming that's a flip from
// 'Light' (boring+light) to 'De Stijl' (destijl+light) — still two different
// strings, still proving the cross-update fires, just re-anchored to the new
// convention instead of the old 'Dark'→'Pip Boy' pair.
suite('BUG-114 (P8.1): syncThemeButtons() — the 4-state mode×theme label matrix, and clicking mode-toggle cross-updates theme-toggle', (ctx) => {
  check(ctx, bug114Obs.boringLight.mode === 'add style?' && bug114Obs.boringLight.theme === 'Light',
    `boring+light: mode-toggle='add style?', theme-toggle='Light' (current-state naming, B21-5) (got ${JSON.stringify(bug114Obs.boringLight)})`);
  check(ctx, bug114Obs.boringDark.mode === 'add style?' && bug114Obs.boringDark.theme === 'Dark',
    `boring+dark: mode-toggle='add style?', theme-toggle='Dark' (current-state naming, B21-5) (got ${JSON.stringify(bug114Obs.boringDark)})`);
  check(ctx, bug114Obs.destijlLight.mode === 'go boring' && bug114Obs.destijlLight.theme === 'De Stijl',
    `destijl+light: mode-toggle='go boring', theme-toggle='De Stijl' (current-state naming, B21-5 — De Stijl-Light IS the current theme) (got ${JSON.stringify(bug114Obs.destijlLight)})`);
  check(ctx, bug114Obs.destijlDark.mode === 'go boring' && bug114Obs.destijlDark.theme === 'Pip Boy',
    `destijl+dark: mode-toggle='go boring', theme-toggle='Pip Boy' (current-state naming, B21-5 — Pip-Boy IS the current theme) (got ${JSON.stringify(bug114Obs.destijlDark)})`);
  check(ctx, bug114Obs.beforeModeClick.mode === 'add style?' && bug114Obs.beforeModeClick.theme === 'Light',
    'pre-click state is boring+light as set up (theme-toggle already reads the current theme, B21-5)');
  check(ctx, bug114Obs.afterModeClick.mode === 'go boring' && bug114Obs.afterModeClick.theme === 'De Stijl',
    `clicking #mode-toggle updates BOTH labels in the same call — the underlying THEME never changed (still light), but theme-toggle's text still flips 'Light'->'De Stijl' because the mode flip alone changes what the current-state name IS (got ${JSON.stringify(bug114Obs.afterModeClick)})`);
});

// ── BUG-097 — ⌘A scoped to #console-body outside editable fields ──────────────
const bug097Obs = await (async () => {
  const obs = {};
  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;
  const { init } = await import(JS('app.js'));
  await init();
  clearConsole();
  appendBlock({ type: 'echo', text: 'summarize price' });
  appendBlock({ type: 'display', text: 'some result text' });

  // Case 1: activeElement outside any editable field (default = <body>).
  window.getSelection().removeAllRanges();
  const ev1 = new dom.window.KeyboardEvent('keydown', { key: 'a', metaKey: true, bubbles: true, cancelable: true });
  document.dispatchEvent(ev1);
  obs.outsidePrevented = ev1.defaultPrevented;
  obs.selectedText = window.getSelection().toString();

  // Case 2: focus inside #cmd-input (editable) — native select-all untouched.
  const input = document.getElementById('cmd-input');
  input.focus();
  const ev2 = new dom.window.KeyboardEvent('keydown', { key: 'a', metaKey: true, bubbles: true, cancelable: true });
  input.dispatchEvent(ev2);
  obs.inputDefaultPrevented = ev2.defaultPrevented;

  window.getSelection().removeAllRanges();
  document.body.innerHTML = '';
  return obs;
})();

suite('BUG-097 (P8.1-T2): Cmd/Ctrl+A scopes to #console-body when focus is outside any editable field; native select-all is untouched inside one', (ctx) => {
  check(ctx, bug097Obs.outsidePrevented === true, 'the shortcut preventDefaults when activeElement is not editable');
  check(ctx, bug097Obs.selectedText.includes('summarize price') && bug097Obs.selectedText.includes('some result text'),
    `window.getSelection() spans #console-body's content (got ${JSON.stringify(bug097Obs.selectedText)}) — jsdom's Selection API supports selectAllChildren, so this pins the real outcome, not just a preventDefault/no-throw fallback`);
  check(ctx, bug097Obs.inputDefaultPrevented === false, 'with focus in #cmd-input, the handler leaves the keydown\'s default un-prevented (native select-all applies)');
});

