// ── T3 — output fold/unfold: positional grouping, textContent stability ───────
suite('T3 (P8.1): echo fold-heads group following siblings (.block-folded/.fold-closed/data-fold-count/aria-expanded); textContent is byte-identical across a fold cycle; pre-echo blocks are untouched', (ctx) => {
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  const body = document.getElementById('console-body');
  initConsole(body, document.getElementById('console-empty'), null);
  clearConsole();
  window.getSelection().removeAllRanges();

  // A block appended before any echo has no fold head to its left.
  appendBlock({ type: 'display', text: 'boot-time note' });
  const preEchoEl = body.querySelector('.block-display');

  appendBlock({ type: 'echo', text: 'regress price mpg' });
  const headEl = body.querySelector('.block-fold-head');
  appendBlock(loadFix('dom/logit_estimation.json'));
  appendBlock({ type: 'display', text: 'note after' });

  const blocksBefore = [...body.children];
  check(ctx, blocksBefore.length === 4, `four blocks in the DOM (got ${blocksBefore.length})`);
  const textBefore = blocksBefore.map(b => b.textContent);

  check(ctx, headEl.getAttribute('aria-expanded') === 'true', 'fold head starts aria-expanded=true');
  check(ctx, !headEl.classList.contains('fold-closed'), 'fold head starts without .fold-closed');

  headEl.click();   // fold

  const estEl = body.querySelector('.block-estimation');
  const trailingDisplayEl = [...body.querySelectorAll('.block-display')][1];
  check(ctx, estEl.classList.contains('block-folded'), 'the estimation member gets .block-folded on fold');
  check(ctx, trailingDisplayEl.classList.contains('block-folded'), 'the trailing display member gets .block-folded on fold');
  check(ctx, !preEchoEl.classList.contains('block-folded'), 'the pre-echo display block (no fold head to its left) is never folded');
  check(ctx, headEl.classList.contains('fold-closed'), 'fold head gets .fold-closed');
  check(ctx, headEl.dataset.foldCount === '2', `fold head data-fold-count === '2' (got ${JSON.stringify(headEl.dataset.foldCount)})`);
  check(ctx, headEl.getAttribute('aria-expanded') === 'false', 'fold head aria-expanded flips to false');

  headEl.click();   // unfold

  check(ctx, !estEl.classList.contains('block-folded'), 'estimation member restored after the second click');
  check(ctx, !trailingDisplayEl.classList.contains('block-folded'), 'trailing display member restored after the second click');
  check(ctx, !headEl.classList.contains('fold-closed'), 'fold head loses .fold-closed on unfold');
  check(ctx, headEl.dataset.foldCount === undefined, 'fold head loses data-fold-count on unfold');
  check(ctx, headEl.getAttribute('aria-expanded') === 'true', 'fold head aria-expanded restored to true');

  const textAfter = [...body.children].map(b => b.textContent);
  check(ctx, JSON.stringify(textBefore) === JSON.stringify(textAfter),
    'every block\'s textContent is byte-identical before vs. after the fold/unfold round trip');

  window.getSelection().removeAllRanges();
  clearConsole();
  document.body.innerHTML = '';
});

