// ── onSaveResults strip precondition ───────────────────────────────────────────
// onSaveResults() itself is private and not exported. This pins the
// PRECONDITION its clone-and-remove mechanism (app.js:2215-2226, "A10 (P8.1):
// strip UI action bars ... from the saved text") depends on: a block that
// carries .console-action nodes must lose that text once cloned+stripped,
// while a block with none returns textContent unchanged. The helper below is
// a verbatim mirror of onSaveResults()'s own blockText(), used ONLY to
// observe — not to substitute for — the real (private) code path.
suite('onSaveResults strip precondition (P8.1): a clone with .console-action removed drops "Copy table"; a bar-less block is untouched', (ctx) => {
  document.body.innerHTML =
    '<div id="console-wrap"><div id="console-body"></div></div><div id="console-empty"></div>';
  const body = document.getElementById('console-body');
  initConsole(body, document.getElementById('console-empty'), null);
  clearConsole();

  appendBlock(loadFix('dom/logit_estimation.json'));
  appendBlock({ type: 'echo', text: 'summarize mpg' });

  const estEl  = body.querySelector('.block-estimation');
  const echoEl = body.querySelector('.block-echo');

  const blockText = (b) => {
    if (!b.querySelector('.console-action')) return b.textContent;
    const clone = b.cloneNode(true);
    clone.querySelectorAll('.console-action').forEach(el => el.remove());
    return clone.textContent;
  };

  check(ctx, estEl.textContent.includes('Copy table'), 'the live estimation block textContent includes "Copy table" (the copy-bar chrome)');
  const stripped = blockText(estEl);
  check(ctx, !stripped.includes('Copy table'), 'the clone-and-remove mechanism strips "Copy table" out of the text a save would use');
  check(ctx, estEl.textContent.includes('Copy table'), 'the LIVE DOM node is untouched (clone, not mutate-in-place)');
  check(ctx, blockText(echoEl) === echoEl.textContent, 'a block with no .console-action returns textContent unchanged (no clone needed)');

  clearConsole();
  document.body.innerHTML = '';
});

// ── A11 — smart-quote normalization (paste) ────────────────────────────────────
const a11Obs = await (async () => {
  const obs = {};
  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      <div id="doedit-overlay" class="console-overlay">
        <div class="doedit-bar">
          <span class="doedit-title" id="doedit-title">Do-file Editor</span>
          <button id="doedit-clear" class="doedit-btn">Clear</button>
        </div>
        <textarea id="doedit-text"></textarea>
      </div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span id="status-flash" hidden></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;
  localStorage.removeItem('piet-paste-autorun');
  const { init } = await import(JS('app.js'));
  await init();

  // Force a known-clean do-editor dirty state regardless of any residual
  // module state left by earlier suites in this file (the Clear button is
  // the same real path a user would use).
  document.getElementById('doedit-clear').click();

  function dispatchPasteOn(el, text) {
    const ev = new dom.window.Event('paste', { bubbles: true, cancelable: true });
    ev.clipboardData = { getData: () => text };
    el.dispatchEvent(ev);
    return ev;
  }
  const settle = () => new Promise(r => setTimeout(r, 0));

  // 1. cmd-input, single effective line, smart double-quotes.
  const input = document.getElementById('cmd-input');
  input.value = '';
  input.focus();
  const ev1 = dispatchPasteOn(input, 'use “myfile.dta”');
  obs.singleLinePrevented = ev1.defaultPrevented;
  obs.singleLineValue = input.value;

  // 2. cmd-input, multi-line, smart quotes normalized before loading the editor.
  input.value = '';
  dispatchPasteOn(input, 'use “myfile.dta”\nsummarize price');
  await settle();
  obs.multiLineEditorText = document.getElementById('doedit-text').value;

  // 3. do-editor paste (smart single-quotes) — also dirty-marks the buffer.
  const ta = document.getElementById('doedit-text');
  ta.value = '';
  ta.focus();
  const ev3 = dispatchPasteOn(ta, 'local x = ‘hello’');
  obs.doeditPrevented = ev3.defaultPrevented;
  obs.doeditValue = ta.value;
  obs.doeditTitleAfterPaste = document.getElementById('doedit-title').textContent;

  document.body.innerHTML = '';
  return obs;
})();

suite('A11 (P8.1-T5): smart-quote normalization on paste — #cmd-input (single- and multi-line) and #doedit-text', (ctx) => {
  check(ctx, a11Obs.singleLinePrevented === true, 'single-line cmd-input paste with smart quotes is intercepted (preventDefault)');
  check(ctx, a11Obs.singleLineValue === 'use "myfile.dta"', `cmd-input value normalizes to straight quotes (got ${JSON.stringify(a11Obs.singleLineValue)})`);
  check(ctx, a11Obs.multiLineEditorText === 'use "myfile.dta"\nsummarize price',
    `multi-line paste normalizes quotes before loading the do-editor (got ${JSON.stringify(a11Obs.multiLineEditorText)})`);
  check(ctx, a11Obs.doeditPrevented === true, 'do-editor paste with smart quotes is intercepted (preventDefault)');
  check(ctx, a11Obs.doeditValue === "local x = 'hello'", `do-editor value normalizes smart single-quotes too (got ${JSON.stringify(a11Obs.doeditValue)})`);
  check(ctx, a11Obs.doeditTitleAfterPaste.endsWith(' *'), 'the normalize-paste path also dirty-marks the buffer (title gains " *")');
});

