  // 3. Only ONE docked: stays hidden, but a custom ratio2 still applies.
  localStorage.setItem('piet-split', JSON.stringify({
    on: true, docked: ['doedit-overlay'], ratio: 50, ratio2: { w1: 2.5, w2: 0.5 },
  }));
  buildDom();
  await init();
