// ── T4 — gutter.js line-number gutter ──────────────────────────────────────────
// gutter.js is a process-wide singleton by DESIGN (initGutter() one-shot DOM-
// wraps #doedit-text — see its own doc comment on idempotency). Every app.js
// suite above that includes #doedit-text already triggers it via init(), so
// by this point in the file the canonical instance's _gutterEl is long since
// non-null. A cache-busted re-import (a distinct specifier string, hence a
// genuinely fresh module registry entry with its own null _gutterEl) lets
// this suite exercise the REAL exported initGutter()/setGutterErrorLine()/
// clearGutterErrorLine() against a controlled fixture without fighting that
// singleton.
const gutterMod = await import(JS('gutter.js') + '?domtest-gutter-on=' + Date.now() + Math.random());
const t4Obs = (() => {
  const obs = {};
  document.body.innerHTML = `
    <div id="doedit-overlay">
      <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span></div>
      <textarea id="doedit-text"></textarea>
    </div>`;
  localStorage.removeItem('piet-editor-gutter');
  gutterMod.initGutter();

  const row = document.getElementById('doedit-editor-row');
  const gutterEl = document.getElementById('doedit-gutter');
  obs.rowBuilt = !!row;
  obs.gutterBuilt = !!gutterEl;
  obs.taMovedInsideRow = !!row && row.contains(document.getElementById('doedit-text'));
  obs.lineCount1 = gutterEl.querySelectorAll('.gutter-line').length;
  obs.lineText1  = [...gutterEl.querySelectorAll('.gutter-line')].map(s => s.textContent);

  const ta = document.getElementById('doedit-text');
  ta.value = 'line1\nline2\nline3';
  ta.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
  obs.lineCount2 = gutterEl.querySelectorAll('.gutter-line').length;
  obs.lineText2  = [...gutterEl.querySelectorAll('.gutter-line')].map(s => s.textContent);

  gutterMod.setGutterErrorLine(2);
  const errEls = [...gutterEl.querySelectorAll('.gutter-line')].filter(s => s.classList.contains('gutter-err-line'));
  obs.errLineCount = errEls.length;
  obs.errLineText  = errEls[0]?.textContent;

  gutterMod.clearGutterErrorLine();
  obs.errLineCountAfterClear = gutterEl.querySelectorAll('.gutter-err-line').length;

  document.body.innerHTML = '';
  return obs;
})();

suite('T4 (P8.1): gutter.js — initGutter() wraps #doedit-text in #doedit-editor-row/#doedit-gutter; line count tracks input; setGutterErrorLine highlights', (ctx) => {
  check(ctx, t4Obs.rowBuilt, '#doedit-editor-row is built');
  check(ctx, t4Obs.gutterBuilt, '#doedit-gutter is built');
  check(ctx, t4Obs.taMovedInsideRow, '#doedit-text is MOVED inside #doedit-editor-row (same node, not cloned)');
  check(ctx, t4Obs.lineCount1 === 1, `an empty textarea gets exactly 1 .gutter-line (got ${t4Obs.lineCount1})`);
  check(ctx, JSON.stringify(t4Obs.lineText1) === JSON.stringify(['1']), 'the sole line is numbered "1"');
  check(ctx, t4Obs.lineCount2 === 3, `after a 3-line 'input' event, the gutter rebuilds to 3 .gutter-line spans (got ${t4Obs.lineCount2})`);
  check(ctx, JSON.stringify(t4Obs.lineText2) === JSON.stringify(['1', '2', '3']), 'line numbers are sequential 1/2/3');
  check(ctx, t4Obs.errLineCount === 1 && t4Obs.errLineText === '2', 'setGutterErrorLine(2) highlights exactly line 2 (.gutter-err-line)');
  check(ctx, t4Obs.errLineCountAfterClear === 0, 'clearGutterErrorLine() removes the highlight');
});

