// ── Recent files — honest empty state, replaced by a real entry ───────────────
const recentObs = await (async () => {
  const obs = {};
  const SRC = 'summarize price';
  let pickerPath = '/fake/dir/recentme.do';
  let hydratedUiState = null;
  let holdRead = false;
  const readPaths = [], openPaths = [], executionKeys = [], mirrors = [], releaseReads = [];
  let pickerCalls = 0;
  dom.window.pietNative = {
    request: async (key, body) => {
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'settings.get': return hydratedUiState ? { ui_state: hydratedUiState } : {};
        case 'settings.set':
          if (body.ui_state) mirrors.push(body.ui_state);
          return {};
        case 'dialog.open':
          pickerCalls++;
          return { path: pickerPath };
        case 'file.read':
          readPaths.push(body.path);
          if (holdRead) await new Promise(resolve => releaseReads.push(resolve));
          return { source: SRC, resolved_path: body.path };
        case 'open':
          openPaths.push(body.filepath);
          return { action: 'open', varlist_after: [], n_rows_after: 0 };
        case 'command': case 'do': case 'do_string':
          executionKeys.push(key);
          return { blocks: [] };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        default:             return {};
      }
    },
  };
  const markup = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      <div id="doedit-overlay" class="console-overlay">
        <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span></div>
        <textarea id="doedit-text"></textarea>
      </div>
    </div>
    <nav class="toolbar-menu">
      <div class="menu-dropdown">
        <a href="#" tabindex="0">File ▾</a>
        <div class="menu-dropdown-content">
          <a href="#" data-action="open">Open Data…</a>
          <a href="#" data-action="do-open">Open do-file…</a>
          <div class="menu-recent-group" id="file-menu-recent-group" hidden>
            <div class="menu-dropdown-sep" role="separator"></div>
            <div class="menu-recent-label">Recent</div>
            <div id="file-menu-recent"></div>
          </div>
        </div>
      </div>
    </nav>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;
  document.body.innerHTML = markup;
  localStorage.removeItem('piet-recent-files');
  localStorage.removeItem('piet-paste-autorun');
  const { init } = await import(JS('app.js'));
  await init();
  const settle = () => new Promise(r => setTimeout(r, 10));

  const group = document.getElementById('file-menu-recent-group');
  const list  = document.getElementById('file-menu-recent');
  obs.emptyGroupHidden = group.hidden;
  obs.emptyListText    = list.textContent;
  obs.emptyRowClass    = list.querySelector('.menu-recent-empty')?.className ?? null;

  document.querySelector('[data-action="do-open"]').click();
  await settle(); await settle();

  obs.afterGroupHidden = group.hidden;
  obs.afterHasEmptyRow = !!list.querySelector('.menu-recent-empty');
  obs.afterEntryText   = list.querySelector('a')?.textContent ?? null;
  obs.afterEntryTitle  = list.querySelector('a')?.title ?? null;

  // Exercise tracking through real picker opens, then inspect storage and menu.
  // The final path also checks Windows separators and literal text rendering.
  const paths = Array.from({ length: 10 }, (_, i) =>
    i === 9 ? ['C:', 'data', '<recent>.do'].join(String.fromCharCode(92)) : `/fake/dir/entry${i}.do`);
  for (const path of paths) {
    pickerPath = path;
    document.querySelector('[data-action="do-open"]').click();
    await settle();
  }
  const entries = () => JSON.parse(localStorage.getItem('piet-recent-files') || '[]');
  obs.cappedPaths = entries().map(entry => entry.path);
  obs.expectedCappedPaths = paths.slice(2).reverse();
  obs.windowsLabel = list.querySelector('a')?.textContent;
  obs.windowsIsText = list.querySelector('a')?.children.length === 0;
  pickerPath = paths[4];
  document.querySelector('[data-action="do-open"]').click();
  await settle();
  obs.dedupedPaths = entries().map(entry => entry.path);
  obs.expectedDedupedPaths = [paths[4], ...obs.expectedCappedPaths.filter(path => path !== paths[4])];

  const pickerCallsBeforeRecent = pickerCalls;
  document.getElementById('doedit-text').value = 'replaced by recent reopen';
  list.querySelector('a').click();
  await settle();
  obs.recentReadPath = readPaths.at(-1);
  obs.recentEditorText = document.getElementById('doedit-text').value;
  obs.recentEditorOpen = document.getElementById('doedit-overlay').classList.contains('open');
  obs.recentSkippedPicker = pickerCalls === pickerCallsBeforeRecent;
  obs.recentDidNotExecute = executionKeys.length === 0;

  // Hold an actual file read in flight so the app owns its normal busy lock.
  // A second recent click must not issue another read or a data-open request.
  holdRead = true;
  list.querySelector('a').click();
  const readCountWhileBusy = readPaths.length;
  const openCountWhileBusy = openPaths.length;
  list.querySelectorAll('a')[1].click();
  await settle();
  obs.busyBlocked = document.getElementById('cmd-input').disabled &&
    readPaths.length === readCountWhileBusy && openPaths.length === openCountWhileBusy;
  holdRead = false;
  releaseReads.splice(0).forEach(release => release());
  await settle();

  // Data entries use the existing known-path open route as well.
  pickerPath = '/fake/dir/recentdata.dta';
  document.querySelector('[data-action="open"]').click();
  await settle();
  const pickerCallsBeforeData = pickerCalls;
  const openCountBeforeData = openPaths.length;
  list.querySelector('a').click();
  await settle();
  obs.recentDataOpen = openPaths.length === openCountBeforeData + 1 &&
    openPaths.at(-1) === pickerPath && pickerCalls === pickerCallsBeforeData;

  // The debounced native settings mirror must still contain the current MRU.
  const storedPaths = entries().map(entry => entry.path);
  await new Promise(resolve => setTimeout(resolve, 450));
  hydratedUiState = mirrors.at(-1) || null;
  obs.mirroredPaths = hydratedUiState
    ? JSON.parse(JSON.parse(hydratedUiState)['piet-recent-files'] || '[]').map(entry => entry.path)
    : [];
  obs.expectedStoredPaths = storedPaths;
  // Simulate a new document with empty local storage and a native saved UI blob.
  localStorage.removeItem('piet-recent-files');
  document.body.innerHTML = markup;
  await init();
  obs.restoredPaths = Array.from(document.querySelectorAll('#file-menu-recent a'), a => a.title);

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  localStorage.removeItem('piet-recent-files');
  return obs;
})();

suite('Recent files (P8.1): empty localStorage shows a visible "(no recent files)" row; a tracked entry replaces it', (ctx) => {
  check(ctx, recentObs.emptyGroupHidden === false, 'the Recent group is VISIBLE even with zero entries (discoverability fix)');
  check(ctx, recentObs.emptyListText.includes('(no recent files)'), 'the empty state shows the honest placeholder text');
  check(ctx, recentObs.emptyRowClass === 'menu-recent-item menu-recent-empty', 'the placeholder row carries .menu-recent-empty');
  check(ctx, recentObs.afterGroupHidden === false, 'the group stays visible after a file is opened');
  check(ctx, recentObs.afterHasEmptyRow === false, 'opening a do-file REPLACES the placeholder row (no longer present)');
  check(ctx, recentObs.afterEntryText === 'recentme.do', `the real entry shows the file's basename (got ${JSON.stringify(recentObs.afterEntryText)})`);
  check(ctx, recentObs.afterEntryTitle === '/fake/dir/recentme.do', 'the entry\'s title carries the full path');
  check(ctx, JSON.stringify(recentObs.cappedPaths) === JSON.stringify(recentObs.expectedCappedPaths),
    'ten distinct opens retain the newest eight entries in MRU order');
  check(ctx, JSON.stringify(recentObs.dedupedPaths) === JSON.stringify(recentObs.expectedDedupedPaths),
    'reopening an existing path moves it to the front without duplicates');
  check(ctx, recentObs.windowsLabel === '<recent>.do' && recentObs.windowsIsText,
    `a Windows path displays its basename as literal text rather than HTML (got ${JSON.stringify([recentObs.windowsLabel, recentObs.windowsIsText])})`);
  check(ctx, recentObs.recentReadPath === recentObs.expectedDedupedPaths[0] &&
    recentObs.recentEditorText === 'summarize price' && recentObs.recentEditorOpen,
    'clicking a recent do-file reads the known path and opens its source in the editor');
  check(ctx, recentObs.recentSkippedPicker && recentObs.recentDidNotExecute,
    'recent do-file reopen bypasses the picker and never runs the source');
  check(ctx, recentObs.busyBlocked, 'a recent click while an open is busy issues no second request');
  check(ctx, recentObs.recentDataOpen, 'a recent data click uses the known-path data open route');
  check(ctx, JSON.stringify(recentObs.mirroredPaths) === JSON.stringify(recentObs.expectedStoredPaths),
    'tracking still mirrors the current recent-file list into native ui_state');
  check(ctx, JSON.stringify(recentObs.restoredPaths) === JSON.stringify(recentObs.expectedStoredPaths),
    'a new document renders saved recent entries after native ui_state hydration');
});

// ── T3 addendum (P8.1, operator): ⌥↑/↓ block-group navigation ────────────────
// Restored plan item (UX-054 안2-lite) — its OWN .block-nav-anchor class, not
// C4's .block-active (single-owner invariant, see app.js's handler comment).
const altNavObs = await (async () => {
  const obs = {};
  dom.window.pietNative = {
    request: async (key) => {
      switch (key) {
        case 'varlist': return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history': return { history: [] };
        default:        return {};
      }
    },
  };
  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
    </div>
    <div id="var-list-wrap"></div><ul id="hist-list"></ul>
    <span id="status-file"></span><span id="status-dims"></span><span id="kernel-dot"></span>`;
  const { init } = await import(JS('app.js'));
  await init();
  // Two command groups: echo+display, echo+display (appendBlock tags the echoes .block-fold-head).
  appendBlock({ type: 'echo', text: 'first cmd' });
  appendBlock({ type: 'display', text: 'out 1' });
  appendBlock({ type: 'echo', text: 'second cmd' });
  appendBlock({ type: 'display', text: 'out 2' });
  const body  = document.getElementById('console-body');
  const heads = body.querySelectorAll('.block-fold-head');
  obs.headCount = heads.length;

  const press = (key) => document.dispatchEvent(new dom.window.KeyboardEvent('keydown',
    { key, altKey: true, bubbles: true, cancelable: true }));

  // HARNESS CAVEAT: every prior suite's init() registered its own document-level
  // keydown listener on this shared jsdom document, so one press applies the
  // handler N times (N = accumulated inits — a harness artifact; the real app
  // runs init() once). Per-press step counts are therefore untestable here;
  // assert the FIXED POINTS instead (clamped ends, single-anchor + C4
  // invariants, editable inertness) — all stable under any handler count ≥1.
  press('ArrowUp');   // activates navigation (lands somewhere ≤ last head)
  obs.activatedAnchor = !!body.querySelector('.block-nav-anchor');
  press('ArrowUp'); press('ArrowUp'); press('ArrowUp');   // → clamps at the FIRST head
  obs.clampedUpText = body.querySelector('.block-nav-anchor')?.textContent ?? null;
  obs.anchorCount = body.querySelectorAll('.block-nav-anchor').length;   // single-anchor invariant
  press('ArrowDown'); press('ArrowDown'); press('ArrowDown'); press('ArrowDown');   // → clamps at the LAST head
  obs.clampedDownText = body.querySelector('.block-nav-anchor')?.textContent ?? null;
  obs.activeUntouched = body.querySelectorAll('.block-active').length === 0;   // C4 class never stolen

  // Inside an editable field the shortcut stays native (no anchor movement —
  // every accumulated handler instance takes the same editable-bypass branch).
  document.getElementById('cmd-input').focus();
  press('ArrowUp');
  obs.editableText = body.querySelector('.block-nav-anchor')?.textContent ?? null;

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  return obs;
})();

suite('T3 addendum (P8.1): ⌥↑/↓ jumps between .block-fold-head groups via .block-nav-anchor (own class — C4 .block-active untouched); clamps at ends; inert in editable fields', (ctx) => {
  check(ctx, altNavObs.headCount === 2, 'fixture has 2 fold heads');
  check(ctx, altNavObs.activatedAnchor, '⌥↑ activates a .block-nav-anchor');
  check(ctx, altNavObs.clampedUpText === '. first cmd', `repeated ⌥↑ clamps at the FIRST head, no wrap (got ${JSON.stringify(altNavObs.clampedUpText)})`);
  check(ctx, altNavObs.anchorCount === 1, 'exactly ONE .block-nav-anchor at a time');
  check(ctx, altNavObs.clampedDownText === '. second cmd', 'repeated ⌥↓ clamps at the LAST head');
  check(ctx, altNavObs.activeUntouched, "navigation never touches C4's .block-active");
  check(ctx, altNavObs.editableText === '. second cmd', 'with focus in #cmd-input the shortcut is inert (anchor unmoved)');
});

// ════════════════════════════════════════════════════════════════════════════
// N6 (P8.1-W2, contract_B v2.4.0) — live block streaming dedup.
//   Fake pietNative bridge whose 'do_string' handler pushes {kind:'block'}
//   piet-events SYNCHRONOUSLY (before returning) while the call is still
//   PENDING (a manually-resolved Promise) — mirrors the real ordering
//   (native's runDoInBackground pushes blocks over the RunProgress conduit
//   WHILE the background do-run thread is still working; the do_string
//   response itself only resolves once the whole run finishes). Because
//   calling an async function runs synchronously up to its first await/
//   return, and jsdom's dispatchEvent() invokes listeners synchronously too,
//   everything pushed below is ALREADY rendered into #console-body by the
//   time the triggering .click() call returns control to this script — i.e.
//   genuinely "before resolution", not merely "before the test's own settle()".
// ════════════════════════════════════════════════════════════════════════════
const n6Obs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));
  function pushEvent(detail) {
    dom.window.pietEvents.dispatchEvent(new dom.window.CustomEvent('piet-event', { detail }));
  }

  let resolveRun1;
  const run1Promise = new Promise(resolve => { resolveRun1 = resolve; });

  dom.window.pietNative = {
    request: async (key, body) => {
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        case 'do_string':
          if (body?.source === 'run1') {
            // Two blocks streamed live WHILE this call is still pending.
            pushEvent({ kind: 'block', seq: 0, block: { type: 'display', text: 'streamed line one' } });
            pushEvent({ kind: 'block', seq: 1, block: { type: 'data_mutation', action: 'drop', n_dropped: 3, varlist_after: [], n_rows_after: 0 } });
            return run1Promise;   // stays pending until the test resolves it below
          }
          // run2: back-compat leg — a transport that never streams at all
          // (no piet-event ever pushed, `streamed` omitted entirely).
          return {
            blocks: [
              { type: 'display', text: 'compat A' },
              { type: 'display', text: 'compat B' },
            ],
          };
        default: return {};
      }
    },
  };
  dom.window.pietEvents = new dom.window.EventTarget();

  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      <div id="doedit-overlay" class="console-overlay open">
        <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span>
          <button id="doedit-run" type="button">Run</button>
        </div>
        <textarea id="doedit-text">run1</textarea>
      </div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span id="status-flash" hidden></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;

  const { init } = await import(JS('app.js'));
  await init();

  const body = () => document.getElementById('console-body');
  const blockCount = () => body().querySelectorAll('.block').length;

  document.getElementById('doedit-run').click();
  // Synchronous chain: click -> runDoEditor -> _runEditorBuffer ->
  // runDoSourceCore -> appendBlock(echo label) -> client.runDoString ->
  // request('do_string') -> both pushEvent() calls dispatch+render
  // SYNCHRONOUSLY, all before the fake bridge ever returns the still-pending
  // run1Promise — so by the time .click() returns here, the streamed blocks
  // are ALREADY in the DOM.
  obs.countWhilePending = blockCount();
  obs.streamedTexts = [...body().children].map(el => el.textContent);
  obs.mutationExtraText = [...body().querySelectorAll('.block-display')]
    .map(el => el.textContent).find(t => t.includes('observations deleted')) ?? null;

  // Resolve with the FULL blocks array (byte-identical to what streamed) PLUS
  // one block that was NEVER streamed, streamed:2 — applyDoResult() must
  // render ONLY blocks[2:] (the trailing new block), never re-render 0/1.
  resolveRun1({
    blocks: [
      { type: 'display', text: 'streamed line one' },
      { type: 'data_mutation', action: 'drop', n_dropped: 3, varlist_after: [], n_rows_after: 0 },
      { type: 'display', text: 'final only line' },
    ],
    streamed: 2,
  });
  await settle(); await settle();
  obs.countAfterResolve = blockCount();
  obs.finalOnlyRenderedOnce =
    [...body().querySelectorAll('.block-display')].filter(el => el.textContent === 'final only line').length;
  obs.streamedLineRenderedOnce =
    [...body().querySelectorAll('.block-display')].filter(el => el.textContent === 'streamed line one').length;

  // ── Leg 2: streamed absent entirely (no piet-event ever fired this run) ->
  //    renders the whole response exactly once (full back-compat). ──
  const countBeforeRun2 = blockCount();
  document.getElementById('doedit-text').value = 'run2';
  document.getElementById('doedit-run').click();
  await settle(); await settle();
  obs.run2NewBlockCount = blockCount() - countBeforeRun2;
  obs.compatARenderedOnce = [...body().querySelectorAll('.block-display')].filter(el => el.textContent === 'compat A').length;
  obs.compatBRenderedOnce = [...body().querySelectorAll('.block-display')].filter(el => el.textContent === 'compat B').length;

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  delete dom.window.pietEvents;
  return obs;
})();

suite('N6 (P8.1-W2): streaming {kind:"block"} pushes render LIVE during a pending do_string; the final response dedups against `streamed`', (ctx) => {
  check(ctx, n6Obs.countWhilePending === 4,
    `2 streamed blocks (+ the run's own echo label + the streamed mutation's synthesized withMutationSummaries extra) are ALREADY rendered before do_string resolves (got ${n6Obs.countWhilePending})`);
  check(ctx, n6Obs.streamedTexts.some(t => t.includes('streamed line one')),
    "the streamed display block's text is visible before resolution");
  check(ctx, n6Obs.mutationExtraText === '(3 observations deleted)',
    `a streamed data_mutation block gets its withMutationSummaries decoration too, same as the batch path (got ${JSON.stringify(n6Obs.mutationExtraText)})`);
  check(ctx, n6Obs.countAfterResolve === n6Obs.countWhilePending + 1,
    `the final response (streamed:2, 3 total blocks) appends ONLY the one non-streamed tail block — no double-render (before=${n6Obs.countWhilePending}, after=${n6Obs.countAfterResolve})`);
  check(ctx, n6Obs.streamedLineRenderedOnce === 1 && n6Obs.finalOnlyRenderedOnce === 1,
    'neither the streamed block nor the new tail block is duplicated (each renders exactly once)');
});

suite('N6 (P8.1-W2): a transport that never streams (no piet-event push, `streamed` omitted) renders the whole response exactly once (back-compat)', (ctx) => {
  check(ctx, n6Obs.run2NewBlockCount === 3,
    `run2's echo label + both compat blocks all render in the final pass alone (got a delta of ${n6Obs.run2NewBlockCount})`);
  check(ctx, n6Obs.compatARenderedOnce === 1 && n6Obs.compatBRenderedOnce === 1,
    'each block in an unstreamed response renders exactly once');
});

// ════════════════════════════════════════════════════════════════════════════
// N1 (P8.1-W2, contract_B v2.4.0) — save feature-detection (onSaveResults).
//   Native bridge present -> real file.save round trip; {ok:true} flashes the
//   real path and never touches the legacy anchor-download path (structurally
//   unreachable once client.native is truthy — app.js's onSaveResults() early-
//   returns inside the `if (client && client.native)` branch). {ok:false,
//   cancelled:true} -> quiet no-op (no flash, no error). A rejected
//   saveFile() -> one error block, still no "Saved" flash. No bridge at all
//   (mock/browser) -> the ORIGINAL Blob->createObjectURL-><a download> path,
//   byte-unchanged — spied via a monkeypatched HTMLAnchorElement.prototype.
//   click (never invoking jsdom's real navigation, which isn't implemented).
// ════════════════════════════════════════════════════════════════════════════
const n1Obs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));

  function buildDom() {
    document.body.innerHTML = `
      <div id="pane-console">
        <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
        <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
        <div class="console-toolbar"><button id="btn-save-results" type="button">Save Results…</button></div>
      </div>
      <div id="var-list-wrap"></div>
      <ul id="hist-list"></ul>
      <span id="status-file">(no data)</span><span id="status-dims"></span>
      <span id="status-flash" hidden></span>
      <span class="kernel-dot" id="kernel-dot"></span>`;
  }

  const { init } = await import(JS('app.js'));

  // ── Legs 1-3: native bridge present, file.save sequenced ok / cancelled / rejected. ──
  let saveCallN = 0;
  dom.window.pietNative = {
    request: async (key) => {
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'file.save':
          saveCallN++;
          if (saveCallN === 1) return { ok: true, path: '/tmp/x.log' };
          if (saveCallN === 2) return { ok: false, cancelled: true };
          throw { code: 'handler_exception', message: 'disk full' };
        default: return {};
      }
    },
  };
  buildDom();
  await init();
  appendBlock({ type: 'display', text: 'seed result line for Save Results' });

  const flash = document.getElementById('status-flash');
  const errCount = () => document.querySelectorAll('.block-error').length;
  const resetFlash = () => { flash.hidden = true; flash.textContent = ''; };

  resetFlash();
  document.getElementById('btn-save-results').click();
  await settle(); await settle();
  obs.leg1FlashHidden = flash.hidden;
  obs.leg1FlashText   = flash.textContent;
  obs.leg1AnchorCount = document.querySelectorAll('a[download]').length;
  obs.leg1ErrCount    = errCount();

  resetFlash();
  document.getElementById('btn-save-results').click();
  await settle(); await settle();
  obs.leg2FlashHidden = flash.hidden;
  obs.leg2ErrCount    = errCount();

  resetFlash();
  const errBefore = errCount();
  document.getElementById('btn-save-results').click();
  await settle(); await settle();
  obs.leg3FlashHidden   = flash.hidden;
  obs.leg3ErrCountDelta = errCount() - errBefore;
  obs.leg3ErrText       = [...document.querySelectorAll('.block-error')].pop()?.textContent ?? '';

  delete dom.window.pietNative;

  // ── Leg 4: no bridge at all (mock) -> legacy anchor-download path. ──
  const clicks = [];
  const origClick = dom.window.HTMLAnchorElement.prototype.click;
  dom.window.HTMLAnchorElement.prototype.click = function () {
    clicks.push({ download: this.download, hadHref: !!this.href });
  };
  buildDom();
  await init();   // no window.pietNative -> useMock -> client.native is falsy
  appendBlock({ type: 'display', text: 'seed result line, mock mode' });
  document.getElementById('btn-save-results').click();
  await settle(); await settle();
  dom.window.HTMLAnchorElement.prototype.click = origClick;
  obs.legacyClickCount   = clicks.length;
  obs.legacyDownloadName = clicks[0]?.download ?? null;
  obs.legacyHadHref      = clicks[0]?.hadHref ?? false;

  document.body.innerHTML = '';
  return obs;
})();

suite('N1 (P8.1-W2): onSaveResults feature-detects the native bridge — {ok:true} flashes the real path with NO anchor download', (ctx) => {
  check(ctx, n1Obs.leg1FlashHidden === false && n1Obs.leg1FlashText === 'Saved /tmp/x.log',
    `{ok:true,path} flashes "Saved <path>" verbatim (got hidden=${n1Obs.leg1FlashHidden} text=${JSON.stringify(n1Obs.leg1FlashText)})`);
  check(ctx, n1Obs.leg1AnchorCount === 0 && n1Obs.leg1ErrCount === 0,
    'no <a download> element exists (the legacy path never ran on the bridge leg) and no error block appears on a confirmed save');
});

suite('N1 (P8.1-W2): {ok:false,cancelled:true} is a quiet no-op; a REJECTED saveFile() surfaces an error block with NO "Saved" flash', (ctx) => {
  check(ctx, n1Obs.leg2FlashHidden === true && n1Obs.leg2ErrCount === 0,
    'a cancelled native save panel flashes nothing and is not treated as an error');
  check(ctx, n1Obs.leg3FlashHidden === true && n1Obs.leg3ErrCountDelta === 1,
    'a rejected saveFile() never flashes "Saved" (the false-Saved class stays dead) and appends exactly one error block');
  check(ctx, n1Obs.leg3ErrText.includes('Save Results failed'),
    `the error block names the failed operation (got ${JSON.stringify(n1Obs.leg3ErrText)})`);
});

suite('N1 (P8.1-W2): with NO native bridge (mock/browser) the legacy Blob->anchor-download path still runs, byte-unchanged', (ctx) => {
  check(ctx, n1Obs.legacyClickCount === 1,
    'exactly one <a>.click() attempt — the original client-side download idiom');
  check(ctx, !!n1Obs.legacyDownloadName?.startsWith('piet-results-') && n1Obs.legacyDownloadName.endsWith('.log') && n1Obs.legacyHadHref === true,
    `the anchor carries a real blob: href and a piet-results-<timestamp>.log download name (got ${JSON.stringify(n1Obs.legacyDownloadName)})`);
});

// ════════════════════════════════════════════════════════════════════════════
// N2 (P8.1-W2, contract_B v2.4.0) — ui_state hydration/migration.
//   hydrateUiState() is awaited INSIDE init(), positioned BEFORE initPanes()/
//   initGutter()/restoreSplit() (app.js's own doc comment) — restoreSplit()
//   is used here as the observable "consumer" proving the write-through
//   actually lands before anything reads its own localStorage key. A literal
//   <html data-theme> assertion is NOT reachable from this harness: that
//   application happens in index.html's separate inline pre-paint <script>,
//   which dom_runner never executes (see the report's "untestable" list).
// ════════════════════════════════════════════════════════════════════════════
const n2Obs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));
  const settleDebounce = () => new Promise(r => setTimeout(r, 450));   // > app.js's 400ms _uiStatePersistTimer

  function buildDom() {
    document.body.innerHTML = `
      <header id="toolbar">
        <nav class="toolbar-views" aria-label="View">
          <a href="#" class="view-tab active" data-view="results">Results</a>
          <a href="#" class="view-tab" data-view="doedit" data-action="doedit">Do-file Editor</a>
          <a href="#" class="view-tab" data-view="graphics" data-action="graphics">Graphics</a>
          <button id="split-toggle" class="toolbar-mini-btn" type="button" aria-pressed="false">Split</button>
          <button id="layout-variant-toggle" class="toolbar-mini-btn" type="button" hidden aria-pressed="false">Stack</button>
          <button id="reset-layout" class="toolbar-mini-btn" type="button" hidden>Reset layout</button>
        </nav>
      </header>
      <main id="pane-console">
        <div id="results-surface">
          <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
          <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
        </div>
        <div id="split-resizer" class="pane-resizer" hidden></div>
        <div id="split-placeholder" hidden></div>
        <div id="docked-stack">
          <div id="doedit-overlay" class="console-overlay">
            <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span></div>
            <textarea id="doedit-text"></textarea>
          </div>
          <div id="split-resizer-2" class="pane-resizer" hidden></div>
          <div id="graphics-overlay" class="console-overlay">
            <div class="doedit-bar"><span class="doedit-title" id="graphics-title">Graphics</span></div>
            <div id="graphics-gallery" class="graphics-gallery"></div>
          </div>
        </div>
      </main>
      <div id="var-list-wrap"></div>
      <ul id="hist-list"></ul>
      <span id="status-file">(no data)</span><span id="status-dims"></span>
      <span class="kernel-dot" id="kernel-dot"></span>`;
  }

  const { init } = await import(JS('app.js'));

  // ── Leg 1-2: a native bridge whose settings.get returns a ui_state blob
  //    carrying a 'piet-split' entry that does NOT exist locally yet. ──
  const persistedSplit = JSON.stringify({
    on: true, docked: ['doedit-overlay', 'graphics-overlay'], ratio: 60,
    ratio2: { w1: 2, w2: 1 }, layout: 'stack',
  });
  const setSettingsCalls = [];
  dom.window.pietNative = {
    request: async (key, body) => {
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'settings.get':
          return {
            scratch_path: '', default_working_dir: '', default_export_dir: '',
            memory_budget_mb: 0, compute_cores: 0, provenance_hash: false,
            sys: { total_ram_mb: 8192, cpu_count: 4, recommended_budget_mb: 4096 },
            settings_file: '(test)',
            ui_state: JSON.stringify({ 'piet-split': persistedSplit }),
          };
        case 'settings.set':
          setSettingsCalls.push(body);
          return { ok: true };
        default: return {};
      }
    },
  };
  localStorage.removeItem('piet-split');
  buildDom();
  await init();
  await settle();

  // Not a raw string-equality check: restoreSplit()'s own dockSurface() calls
  // (a legitimate downstream CONSUMER of the just-hydrated value) each call
  // persistSplit() internally, which rewrites localStorage['piet-split'] with
  // a freshly-computed blob (adding e.g. `order`) — so the raw string is
  // expected to have already moved on by the time init() fully settles.
  // Compare the semantically-relevant fields that hydration itself supplied.
  let hydratedParsed = null;
  try { hydratedParsed = JSON.parse(localStorage.getItem('piet-split') || 'null'); } catch { /* leave null */ }
  obs.hydratedMatchesBlob = hydratedParsed?.layout === 'stack' &&
    JSON.stringify(hydratedParsed?.docked) === JSON.stringify(['doedit-overlay', 'graphics-overlay']);
  obs.consumerAppliedHydration =
    document.getElementById('pane-console')?.classList.contains('split-stack') === true &&
    document.getElementById('doedit-overlay')?.classList.contains('docked') === true &&
    document.getElementById('graphics-overlay')?.classList.contains('docked') === true;

  // ── Round trip: a FRESH local change flushes into ui_state via the debounce. ──
  setSettingsCalls.length = 0;
  document.getElementById('layout-variant-toggle').click();   // stack -> columns; persistSplit() -> markUiStateDirty()
  const localAfterToggle = localStorage.getItem('piet-split');
  obs.roundTripLocalChanged = localAfterToggle !== persistedSplit;   // proves it's the FRESH value, not the stale hydrated one
  await settleDebounce();
  const lastCall = setSettingsCalls[setSettingsCalls.length - 1];
  let blob = null;
  try { blob = JSON.parse(lastCall?.ui_state ?? 'null'); } catch { /* leave null */ }
  obs.roundTripCallCount = setSettingsCalls.length;
  obs.roundTripMatches   = !!blob && blob['piet-split'] === localAfterToggle;

  delete dom.window.pietNative;
  localStorage.removeItem('piet-split');

  // ── Leg 3: no bridge at all -> hydrate half is a pure no-op, localStorage
  //    is left exactly as it already was. ──
  const sentinel = JSON.stringify({ on: false, sentinel: true });
  localStorage.setItem('piet-split', sentinel);
  buildDom();
  await init();
  await settle();
  obs.noBridgeLocalStorageUntouched = localStorage.getItem('piet-split') === sentinel;

  document.body.innerHTML = '';
  localStorage.removeItem('piet-split');
  return obs;
})();

suite('N2 (P8.1-W2): hydrateUiState() writes the native ui_state blob into localStorage BEFORE restoreSplit() (a same-init() consumer) ever reads it', (ctx) => {
  check(ctx, n2Obs.hydratedMatchesBlob === true,
    'localStorage["piet-split"] is hydrated verbatim from the native ui_state blob (no local value existed before boot)');
  check(ctx, n2Obs.consumerAppliedHydration === true,
    "restoreSplit() (called AFTER hydrateUiState() inside init()) already sees + applies the hydrated layout:'stack' + both-docked state");
});

suite('N2 (P8.1-W2): a fresh local change round-trips into ui_state via the debounced flush', (ctx) => {
  check(ctx, n2Obs.roundTripLocalChanged === true && n2Obs.roundTripCallCount === 1,
    `the local change actually altered localStorage, and exactly ONE settings.set fires after the 400ms debounce (got ${n2Obs.roundTripCallCount} calls)`);
  check(ctx, n2Obs.roundTripMatches === true,
    'the flushed ui_state blob\'s "piet-split" entry equals the CURRENT (post-change) localStorage value, not the stale hydrated one');
});

suite('N2 (P8.1-W2): with no native bridge at all, hydrate is a pure no-op — localStorage is left exactly as it was', (ctx) => {
  check(ctx, n2Obs.noBridgeLocalStorageUntouched === true,
    'a mock/browser session never overwrites a pre-existing localStorage value (no bridge to hydrate FROM)');
});

// ════════════════════════════════════════════════════════════════════════════
// N5 (P8.1-W2, contract_B v2.4.0) — layout variant (columns↔stack) + click-
//   swap. Built from REAL index.html markup (the #docked-stack/#split-
//   resizer-2/#doedit-title/#graphics-title ids + their nesting) rather than
//   a from-scratch fixture — the lane's own throwaway harness had already
//   shown ad hoc fixtures miss these ids. piet.css is already loaded into
//   this shared document's <head> (top of this file), so getComputedStyle()
//   assertions below read the REAL #docked-stack / .split-stack rules.
//   SCOPE (operator time-box): 5 essential checks, one suite. Skipped for
//   time — not asserted here: the columns-variant-while-both-docked
//   intermediate state, toggling stack back to columns, and a SEPARATE
//   restore-from-persistence boot (restoreSplit() consuming a persisted
//   blob IS still covered, just via N2's hydrate-then-restoreSplit suite
//   above, not a dedicated N5 fixture).
// ════════════════════════════════════════════════════════════════════════════
const n5Obs = await (async () => {
  const obs = {};

  function buildDom() {
    document.body.innerHTML = `
      <header id="toolbar">
        <nav class="toolbar-views" aria-label="View">
          <a href="#" class="view-tab active" data-view="results">Results</a>
          <a href="#" class="view-tab" data-view="doedit" data-action="doedit">Do-file Editor</a>
          <a href="#" class="view-tab" data-view="graphics" data-action="graphics">Graphics</a>
          <button id="split-toggle" class="toolbar-mini-btn" type="button" aria-pressed="false">⊟ Split</button>
          <button id="layout-variant-toggle" class="toolbar-mini-btn" type="button" hidden aria-pressed="false">⊞ Stack</button>
          <button id="reset-layout" class="toolbar-mini-btn" type="button" hidden>Reset layout</button>
        </nav>
      </header>
      <main id="pane-console">
        <div id="results-surface">
          <div class="pane-header">Results</div>
          <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
          <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
        </div>
        <div id="split-resizer" class="pane-resizer" role="separator" aria-hidden="true" hidden></div>
        <div id="split-placeholder" class="split-placeholder" hidden></div>
        <div id="browser-overlay" class="console-overlay" hidden></div>
        <div id="docked-stack">
          <div id="doedit-overlay" class="console-overlay">
            <div class="doedit-bar">
              <span class="doedit-title" id="doedit-title">Do-file Editor</span>
              <span class="doedit-actions"><button id="doedit-run" class="doedit-btn">▶ Run</button></span>
            </div>
            <textarea id="doedit-text"></textarea>
          </div>
          <div id="split-resizer-2" class="pane-resizer" role="separator" aria-hidden="true" hidden></div>
          <div id="graphics-overlay" class="console-overlay">
            <div class="doedit-bar">
              <span class="doedit-title" id="graphics-title">Graphics</span>
            </div>
            <div id="graphics-gallery" class="graphics-gallery"></div>
          </div>
        </div>
      </main>
      <div id="var-list-wrap"></div>
      <ul id="hist-list"></ul>
      <span id="status-file">(no data)</span><span id="status-dims"></span>
      <span class="kernel-dot" id="kernel-dot"></span>`;
  }

  const { init } = await import(JS('app.js'));

  dom.window.pietNative = {
    request: async (key) => {
      switch (key) {
        case 'varlist': return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history': return { history: [] };
        default:        return {};
      }
    },
  };

  const fullOrder = () => [...document.getElementById('docked-stack').children].map(el => el.id);
  const pairOrder = () => fullOrder().filter(id => id === 'doedit-overlay' || id === 'graphics-overlay');

  // ── Leg 1: fresh boot, no split at all — #docked-stack is display:contents. ──
  localStorage.removeItem('piet-split');
  buildDom();
  await init();
  obs.defaultDisplay = getComputedStyle(document.getElementById('docked-stack')).display;

  // ── Leg 2: seed BOTH docked ('columns' variant) via the persisted blob,
  //    then click the layout-variant toggle -> 'stack' really changes layout
  //    (both the class AND the real computed display flip). ──
  localStorage.setItem('piet-split', JSON.stringify({
    on: true, docked: ['doedit-overlay', 'graphics-overlay'], ratio: 50, ratio2: { w1: 1, w2: 1 }, layout: 'columns',
  }));
  buildDom();
  await init();
  document.getElementById('layout-variant-toggle').click();
  obs.stackVariantOk =
    document.getElementById('pane-console').classList.contains('split-stack') === true &&
    getComputedStyle(document.getElementById('docked-stack')).display === 'flex' &&
    document.getElementById('layout-variant-toggle').getAttribute('aria-pressed') === 'true';

  // ── Leg 3: click-swap — arm via one title click, resolve via the OTHER. ──
  obs.orderBeforeSwap = pairOrder();
  document.getElementById('doedit-title').click();   // arm
  obs.armedClass = document.querySelector('#doedit-overlay .doedit-bar').classList.contains('swap-armed');
  document.getElementById('graphics-title').click();   // resolve -> swap
  obs.orderAfterSwap = pairOrder();
  obs.resizerSandwichedAfterSwap = fullOrder().join(',') === 'graphics-overlay,split-resizer-2,doedit-overlay';
  obs.neitherArmedAfterSwap =
    !document.querySelector('#doedit-overlay .doedit-bar').classList.contains('swap-armed') &&
    !document.querySelector('#graphics-overlay .doedit-bar').classList.contains('swap-armed');

  // ── Leg 4: the new order + current variant ('stack', from Leg 2) persisted
  //    into the piet-split blob. ──
  let persisted = null;
  try { persisted = JSON.parse(localStorage.getItem('piet-split') || 'null'); } catch { /* leave null */ }
  obs.persistedOrderAndLayoutOk =
    JSON.stringify(persisted?.order) === JSON.stringify(['graphics-overlay', 'doedit-overlay']) &&
    persisted?.layout === 'stack';

  // ── Leg 5 (isolated — see the HARNESS CAVEAT below): Esc disarms a pending
  //    arm WITHOUT performing a swap. ──
  document.getElementById('doedit-title').click();   // arm doedit again
  const orderBeforeEscape = pairOrder();
  // HARNESS CAVEAT (mirrors the T3-addendum/alt-nav suite's own note earlier
  // in this file): every prior suite's init() registered its own document-
  // level keydown listener on this shared jsdom `document` — one Escape
  // dispatch invokes ALL of them in registration order. The FIRST (oldest)
  // one still correctly disarms the swap (module state `_swapArmedId` is
  // genuinely shared/live, so even a stale closure reads/clears the CURRENT
  // value correctly) and stops there via its own early `return` — but each
  // SUBSEQUENT stale handler instance then falls through PAST the (now-
  // cleared) swap check into the OVERLAYS-registry sweep and closes whichever
  // docked overlay it finds still open, cascading (a 2nd stale handler
  // undocks doedit, a 3rd undocks graphics, ...). A real app never has more
  // than one such listener, so this cascade is a pure harness artifact of
  // re-running init() many times against one shared document — NOT a product
  // bug. Only the genuinely stable invariant is asserted below: Escape
  // disarms without ever completing a SWAP (DOM order untouched) — not
  // "everything else about dock/open state stays exactly as it was".
  document.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true }));
  obs.escapeDisarmOk =
    document.querySelector('#doedit-overlay .doedit-bar')?.classList.contains('swap-armed') === false &&
    JSON.stringify(pairOrder()) === JSON.stringify(orderBeforeEscape);

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  localStorage.removeItem('piet-split');
  return obs;
})();

suite('N5 (P8.1-W2): #docked-stack defaults to display:contents, and the layout-variant toggle flips it into a real flex column (stack)', (ctx) => {
  check(ctx, n5Obs.defaultDisplay === 'contents',
    `no split at all: #docked-stack's computed display is 'contents' (got ${n5Obs.defaultDisplay})`);
  check(ctx, n5Obs.stackVariantOk === true,
    "with both surfaces docked, clicking the layout-variant toggle adds .split-stack + the REAL computed display flips to 'flex' + aria-pressed='true'");
});

suite('N5 (P8.1-W2): click-swap — arm via one docked title, resolve via the OTHER, swapping DOM order + persisting it; Esc disarms without swapping', (ctx) => {
  check(ctx, JSON.stringify(n5Obs.orderBeforeSwap) === JSON.stringify(['doedit-overlay', 'graphics-overlay']) && n5Obs.armedClass === true,
    'starts in natural source order; clicking a docked title arms the swap (.swap-armed)');
  check(ctx, JSON.stringify(n5Obs.orderAfterSwap) === JSON.stringify(['graphics-overlay', 'doedit-overlay']) && n5Obs.resizerSandwichedAfterSwap === true && n5Obs.neitherArmedAfterSwap === true,
    `clicking the OTHER docked title swaps the DOM order (resizer stays sandwiched, both bars disarmed) (got ${JSON.stringify(n5Obs.orderAfterSwap)})`);
  check(ctx, n5Obs.persistedOrderAndLayoutOk === true,
    "the swapped order + current layout variant persist into localStorage's piet-split blob");
  check(ctx, n5Obs.escapeDisarmOk === true,
    'Escape removes .swap-armed and never performs the pending swap — DOM order is exactly what it was before the keypress');
});

// ════════════════════════════════════════════════════════════════════════════
// N7 (P8.1-W2, contract_B v2.4.0) — panels.js's lazy client.varDetail() fetch
//   (_maybeFetchVarDetail, PIN-only). panels.js's `_client = new HTTPClient()`
//   is a MODULE-LEVEL singleton constructed at panels.js's FIRST import in
//   this process (transitively, via this file's very first `await
//   import(JS('app.js'))` near the top) — at that point window.pietNative
//   didn't exist yet, so that cached instance's `.native` is permanently null
//   for the rest of the run. A cache-busted re-import (same trick this file's
//   own gutter.js suite already uses below) gets a FRESH module instance
//   whose `_client` snapshots pietNative AFTER we've set it, below.
// ════════════════════════════════════════════════════════════════════════════
const n7Obs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));
  clearVarStatsCache();   // clean slate — B14(a)'s passive cache is a shared module singleton

  const detailCalls = [];
  dom.window.pietNative = {
    request: async (key, body) => {
      if (key === 'var_detail') {
        detailCalls.push(body?.name);
        if (body?.name === 'income') {
          return { name: 'income', dtype: 'f64', format: '%8.0gc', label: 'Per capita personal income', N: 336, n_missing: 0, mean: 13880.0, sd: 1250.5, min: 9000, max: 20000 };
        }
        throw { code: 'bad_request', message: `var_detail: unknown variable '${body?.name}'` };
      }
      return {};
    },
  };

  document.body.innerHTML = `
    <div id="var-list-wrap"></div>
    <div id="properties" aria-label="Variable properties"></div>
    <ul id="hist-list"></ul>
    <input id="cmd-input" type="text">`;

  const panelsMod = await import(JS('panels.js') + '?domtest-n7=' + Date.now() + Math.random());
  const { initPanels, updateVariables } = panelsMod;

  initPanels(document.getElementById('var-list-wrap'), document.getElementById('properties'), document.getElementById('hist-list'));

  updateVariables([
    { name: 'fatal',  dtype: 'f64', format: '%8.0gc', label: 'Fatalities', n_missing: 0 },
    { name: 'income', dtype: 'f64', format: '%8.0gc', label: 'Per capita personal income', n_missing: 0 },
  ]);

  const row = (name) => document.querySelector(`.var-row[data-varname="${name}"]`);

  // ── Hover must NOT fetch (cheap preview only). ──
  row('income').dispatchEvent(new dom.window.Event('mouseenter', { bubbles: true }));
  await settle();
  obs.hoverCallCount = detailCalls.length;

  // ── PIN (click) on a var with nothing cached -> fetches + renders stats. ──
  row('income').click();
  await settle(); await settle();
  obs.pinFetchedIncomeOnce = detailCalls.length === 1 && detailCalls[0] === 'income';
  obs.cardShowsVarDetail   = document.getElementById('properties').textContent.includes('var_detail');

  // ── A second PIN on the SAME var must NOT re-fetch (session cache hit).
  //    Pinning 'fatal' first ALSO attempts (and, per this mock, fails) its
  //    own fetch -- an expected, unrelated call -- so the assertion counts
  //    'income' calls specifically, not the raw total. ──
  row('fatal').click();    // pin elsewhere first (its own var_detail attempt rejects — unrelated)
  await settle();
  row('income').click();   // re-pin income
  await settle();
  obs.reFetchCallCount = detailCalls.filter(n => n === 'income').length;   // still 1 -- _detailCache hit

  // ── Fetch rejection leaves the hint (silent, no throw, no error surfaced). ──
  updateVariables([                              // N7: a varlist change clears _detailCache
    { name: 'ghost',  dtype: 'f64', format: '%9.0g', label: '', n_missing: 0 },
    { name: 'income', dtype: 'f64', format: '%8.0gc', label: 'Per capita personal income', n_missing: 0 },
  ]);
  let threw = false;
  try { row('ghost').click(); await settle(); await settle(); } catch { threw = true; }
  obs.rejectionThrew    = threw;
  obs.rejectionShowsHint = document.getElementById('properties').textContent.includes('summarize를 실행하거나 설정에서 자동요약을 켜세요');

  delete dom.window.pietNative;
  document.body.innerHTML = '';
  clearVarStatsCache();
  return obs;
})();

suite("N7 (P8.1-W2): PIN fires client.varDetail() for an uncached var and renders it; hover never fetches; a session-cache hit skips the re-fetch; rejection is silent", (ctx) => {
  check(ctx, n7Obs.hoverCallCount === 0 && n7Obs.pinFetchedIncomeOnce === true,
    'hovering a row never calls var_detail (cheap preview only); clicking (PIN) an uncached var fetches it for exactly that name');
  check(ctx, n7Obs.cardShowsVarDetail === true,
    'the detail card re-renders with the fetched var_detail moments (the "var_detail" source marker)');
  check(ctx, n7Obs.reFetchCallCount === 1,
    're-pinning the SAME var this session does not re-fetch (in-memory _detailCache hit)');
  check(ctx, n7Obs.rejectionThrew === false && n7Obs.rejectionShowsHint === true,
    'a rejected fetch never escapes as an exception, and the card falls back to the "run summarize" hint (enhancement-only, per _maybeFetchVarDetail\'s doc comment)');
});

// ════════════════════════════════════════════════════════════════════════════
// api.js mock parity (P8.1-W2, N7/N2) — mockVarDetail()'s numbers must match
//   MOCK_VARLIST's own dtype/format + the REAL MOCK_SUMMARIZE traces (same
//   mock-fidelity law as MOCK_COMMAND_REGRESS itself, api.js's file-header
//   comment); getSettings()'s mock must carry default_export_dir:'' and
//   OMIT ui_state entirely (not even '') so hydrateUiState() treats it as
//   "nothing to hydrate", not as an empty-but-present blob.
// ════════════════════════════════════════════════════════════════════════════
const apiMockObs = await (async () => {
  const obs = {};
  const { HTTPClient } = await import(JS('api.js'));
  const client = new HTTPClient(true);   // explicit mock=true, no window detection needed

  obs.fatalDetail   = await client.varDetail('fatal');    // MOCK_SUMMARIZE covers this one
  obs.beertaxDetail = await client.varDetail('beertax');  // ...and this one
  obs.unempDetail   = await client.varDetail('unemp');    // no summarize trace -> no fabricated moments

  let unknownMessage = null;
  try { await client.varDetail('does_not_exist'); }
  catch (err) { unknownMessage = String(err.message ?? err); }
  obs.unknownMessage = unknownMessage;

  obs.settings = await client.getSettings();
  return obs;
})();

suite('api.js mock parity (P8.1-W2): mockVarDetail() numbers are the REAL MOCK_VARLIST/MOCK_SUMMARIZE traces, not fabricated', (ctx) => {
  check(ctx, apiMockObs.fatalDetail.dtype === 'f64' && apiMockObs.fatalDetail.format === '%8.0gc' && apiMockObs.fatalDetail.N === 336,
    `varDetail('fatal') carries the real varlist dtype/format/N (got ${JSON.stringify(apiMockObs.fatalDetail)})`);
  check(ctx, apiMockObs.fatalDetail.mean === 928.6637 && apiMockObs.fatalDetail.sd === 934.0515 && apiMockObs.fatalDetail.min === 79 && apiMockObs.fatalDetail.max === 5504
    && apiMockObs.beertaxDetail.mean === 0.5133 && apiMockObs.beertaxDetail.sd === 0.4778,
    `varDetail('fatal'/'beertax')'s moments are the REAL summarize trace numbers, not fabricated (got fatal=${JSON.stringify(apiMockObs.fatalDetail)})`);
  check(ctx, apiMockObs.unempDetail.name === 'unemp' && apiMockObs.unempDetail.mean === undefined && apiMockObs.unempDetail.N === 336,
    'a var with no summarize trace (unemp) carries N but no fabricated mean/sd/min/max');
  check(ctx, apiMockObs.unknownMessage === "var_detail: unknown variable 'does_not_exist'",
    `an unknown var name rejects with an honest message (got ${JSON.stringify(apiMockObs.unknownMessage)})`);
});

suite("api.js mock parity (P8.1-W2): getSettings() mock carries default_export_dir:'' and OMITS ui_state entirely", (ctx) => {
  check(ctx, apiMockObs.settings.default_export_dir === '' && !Object.prototype.hasOwnProperty.call(apiMockObs.settings, 'ui_state'),
    `getSettings() mock carries default_export_dir:'' and OMITS ui_state entirely -- not even '' -- so hydrateUiState() treats absence as "nothing to hydrate" (got default_export_dir=${JSON.stringify(apiMockObs.settings.default_export_dir)}, has ui_state=${Object.prototype.hasOwnProperty.call(apiMockObs.settings, 'ui_state')})`);
});

// ════════════════════════════════════════════════════════════════════════════
// B30 (bounded transcripts, contract_B 2.5.0) — three response-shape changes,
//   made in lockstep with the native lane (piet/native, out of this file's
//   ownership): (1) a factor var's `levels` string array no longer ships
//   inline on the varlist — n_levels-only, fetched lazily via
//   client.varDetail() on PIN; (2) the do/do_string final response's
//   `blocks` is tail-only (not the full array) once `streamed > 0` — a
//   TEMPORARY compat guard (app.js's _tailBlocksToRender(), removable at
//   2.6.0) handles both the new and legacy shape; (3) a data_mutation block
//   may now omit `varlist_after` entirely if it isn't the run's last one.
// ════════════════════════════════════════════════════════════════════════════

// ── B30-1: _tailBlocksToRender() compat guard — same fake-bridge + ──────────
//    pushEvent() scaffold as the N6 suite above (do_string handler pushes
//    {kind:'block'} events synchronously, then resolves the final response
//    with a crafted blocks/streamed pair). Three runs, one per shape:
//      runA: NEW shape          — final `blocks` is tail-only (a cancel-style
//            block), blocks.length (1) <= streamed (2).
//      runB: NEW shape, EMPTY   — final `blocks` is [], streamed (2).
//      runC: LEGACY shape       — final `blocks` is the FULL array (streamed
//            ones included), blocks.length (3) > streamed (2) — the same
//            shape N6's own suite already exercises (and must keep passing
//            unmodified — this run repeats it here so THIS suite is a
//            complete, self-contained demonstration of both compat-guard
//            branches rather than depending on a reader cross-referencing N6).
const b30TailObs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));
  function pushEvent(detail) {
    dom.window.pietEvents.dispatchEvent(new dom.window.CustomEvent('piet-event', { detail }));
  }

  let resolveRunA, resolveRunB, resolveRunC;
  const runAPromise = new Promise(resolve => { resolveRunA = resolve; });
  const runBPromise = new Promise(resolve => { resolveRunB = resolve; });
  const runCPromise = new Promise(resolve => { resolveRunC = resolve; });

  dom.window.pietNative = {
    request: async (key, body) => {
      switch (key) {
        case 'varlist':      return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        case 'do_string':
          if (body?.source === 'runA') {
            pushEvent({ kind: 'block', seq: 0, block: { type: 'display', text: 'runA streamed one' } });
            pushEvent({ kind: 'block', seq: 1, block: { type: 'display', text: 'runA streamed two' } });
            return runAPromise;
          }
          if (body?.source === 'runB') {
            pushEvent({ kind: 'block', seq: 0, block: { type: 'display', text: 'runB streamed one' } });
            pushEvent({ kind: 'block', seq: 1, block: { type: 'display', text: 'runB streamed two' } });
            return runBPromise;
          }
          if (body?.source === 'runC') {
            pushEvent({ kind: 'block', seq: 0, block: { type: 'display', text: 'runC streamed one' } });
            pushEvent({ kind: 'block', seq: 1, block: { type: 'display', text: 'runC streamed two' } });
            return runCPromise;
          }
          return { blocks: [] };
        default: return {};
      }
    },
  };
  dom.window.pietEvents = new dom.window.EventTarget();

  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      <div id="doedit-overlay" class="console-overlay open">
        <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span>
          <button id="doedit-run" type="button">Run</button>
        </div>
        <textarea id="doedit-text">runA</textarea>
      </div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span id="status-flash" hidden></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;

  const { init } = await import(JS('app.js'));
  await init();

  const body = () => document.getElementById('console-body');
  const blockCount = () => body().querySelectorAll('.block').length;
  const textsOf = (cls) => [...body().querySelectorAll(cls)].map(el => el.textContent);

  // ── runA: NEW tail-only shape carrying the REAL cancel block shape ──
  //    (piet/native/src/doexec.cpp's cancelledBlock(): an `error` block,
  //    code:"engine_error", NOT a synthetic display block — authentic
  //    fixture, not an invented placeholder).
  document.getElementById('doedit-run').click();
  const countA0 = blockCount();
  resolveRunA({
    blocks: [{ type: 'error', code: 'engine_error', message: 'run cancelled', reason: 'cancelled' }],
    streamed: 2,
  });
  await settle(); await settle();
  obs.runA_newCount     = blockCount() - countA0;
  obs.runA_cancelOnce   = textsOf('.block-error').filter(t => t.includes('run cancelled')).length;
  obs.runA_streamedOnce = textsOf('.block-display').filter(t => t === 'runA streamed one').length === 1
                        && textsOf('.block-display').filter(t => t === 'runA streamed two').length === 1;

  // ── runB: NEW tail-only shape whose tail is COMPLETELY empty. ──
  document.getElementById('doedit-text').value = 'runB';
  document.getElementById('doedit-run').click();
  const countB0 = blockCount();
  resolveRunB({ blocks: [], streamed: 2 });
  await settle(); await settle();
  obs.runB_newCount = blockCount() - countB0;

  // ── runC: LEGACY full-array shape (blocks.length > streamed) — the ──
  //    compat guard's OTHER branch, same shape N6 exercises above.
  document.getElementById('doedit-text').value = 'runC';
  document.getElementById('doedit-run').click();
  const countC0 = blockCount();
  resolveRunC({
    blocks: [
      { type: 'display', text: 'runC streamed one' },
      { type: 'display', text: 'runC streamed two' },
      { type: 'display', text: 'runC tail only' },
    ],
    streamed: 2,
  });
  await settle(); await settle();
  obs.runC_newCount     = blockCount() - countC0;
  obs.runC_tailOnce     = textsOf('.block-display').filter(t => t === 'runC tail only').length;
  obs.runC_streamedOnce = textsOf('.block-display').filter(t => t === 'runC streamed one').length === 1
                        && textsOf('.block-display').filter(t => t === 'runC streamed two').length === 1;

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  delete dom.window.pietEvents;
  return obs;
})();

