// ── B30-2: factor-levels placeholder + lazy client.varDetail() fetch — ──────
//    same cache-busted re-import + fake-bridge scaffold as the N7 suite
//    above (that module-level `_client` singleton note applies here too). A
//    factor var arrives WITHOUT inline `levels` (n_levels-only, the new wire
//    shape) — the card must show a compact "N levels — click to load"
//    placeholder, then PIN (the row's existing click-to-insert gesture,
//    _pinAndInsert -> _maybeFetchVarDetail) fetches var_detail and the card
//    re-renders with the real level strings.
const b30LevelsObs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));
  clearVarStatsCache();   // clean slate — B14(a)'s passive cache is a shared module singleton

  const detailCalls = [];
  dom.window.pietNative = {
    request: async (key, body) => {
      if (key === 'var_detail') {
        detailCalls.push(body?.name);
        if (body?.name === 'breath') {
          // Factor dtype: real native var_detail omits numeric moments for
          // factor/string columns (routes.cpp) — levels only, same as the
          // mock (api.js's mockVarDetail()/MOCK_FACTOR_LEVELS).
          return { name: 'breath', dtype: 'factor', format: '%8.0g', label: 'Preliminary breath test law', N: 336, n_missing: 0, levels: ['no', 'yes'] };
        }
        throw { code: 'bad_request', message: `var_detail: unknown variable '${body?.name}'` };
      }
      return {};
    },
  };

  document.body.innerHTML = `
    <div id="var-list-wrap"></div>
    <div id="properties" aria-label="Variable properties"></div>
    <ul id="hist-list"></ul>
    <input id="cmd-input" type="text">`;

  const panelsMod = await import(JS('panels.js') + '?domtest-b30levels=' + Date.now() + Math.random());
  const { initPanels, updateVariables } = panelsMod;

  initPanels(document.getElementById('var-list-wrap'), document.getElementById('properties'), document.getElementById('hist-list'));

  // B.3.0 wire shape: n_levels present, NO inline `levels` array.
  updateVariables([
    { name: 'breath', dtype: 'factor', format: '%8.0g', label: 'Preliminary breath test law', n_levels: 2, n_missing: 0 },
  ]);

  const row = document.querySelector('.var-row[data-varname="breath"]');
  const cardText = () => document.getElementById('properties').textContent;

  // ── Hover: placeholder shows, no fetch (cheap preview only — mirrors N7). ──
  row.dispatchEvent(new dom.window.Event('mouseenter', { bubbles: true }));
  await settle();
  obs.hoverPlaceholderText = cardText();
  obs.hoverCallCount = detailCalls.length;

  // ── PIN (click): placeholder still visible synchronously (before the
  //    microtask fetch resolves), THEN the fetch resolves and the card
  //    re-renders with the real level strings. ──
  row.click();
  obs.pinPlaceholderText = cardText();   // captured synchronously, before the fetch resolves
  await settle(); await settle();
  obs.pinFetchedBreathOnce = detailCalls.length === 1 && detailCalls[0] === 'breath';
  obs.pinResolvedText = cardText();

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  clearVarStatsCache();
  return obs;
})();

suite('B30-2 (bounded transcripts, contract_B 2.5.0): a factor var with n_levels but no inline `levels` shows a "click to load" placeholder; hover never fetches; PIN fetches var_detail once and re-renders with the real level strings', (ctx) => {
  check(ctx, b30LevelsObs.hoverPlaceholderText.includes('2 levels — click to load'),
    `hovering a factor var with no inline levels shows the n_levels placeholder (got ${JSON.stringify(b30LevelsObs.hoverPlaceholderText)})`);
  check(ctx, b30LevelsObs.hoverCallCount === 0,
    'hovering never calls var_detail (cheap preview only, same N7 discipline)');
  check(ctx, b30LevelsObs.pinPlaceholderText.includes('2 levels — click to load'),
    'immediately after PIN (before the fetch resolves) the card still shows the placeholder, not a blank/broken state');
  check(ctx, b30LevelsObs.pinFetchedBreathOnce === true,
    'PIN fetches var_detail exactly once for the pinned var');
  check(ctx, b30LevelsObs.pinResolvedText.includes('no, yes') && !b30LevelsObs.pinResolvedText.includes('click to load'),
    `once the fetch resolves the card re-renders with the REAL level strings and the placeholder is gone (got ${JSON.stringify(b30LevelsObs.pinResolvedText)})`);
});

// ── B30-3: a data_mutation block missing `varlist_after` (native's F8 ───────
//    coalesceMutationVarlists, piet/native/src/doexec.cpp — verified in this
//    same worktree) strips it from every data_mutation EXCEPT the last one
//    THAT CARRIES IT within the blocks ONE top-level do-file item produced.
//    That "one top-level item" is a single command OR one whole loop/if
//    body's aggregated output — NOT separate top-level lines (each plain
//    command is dispatched, and coalesced, on its own, so a plain two-line
//    do-file never actually exhibits this shape). The realistic trigger is a
//    loop with multiple internal mutations, e.g. `forvalues i=1/2 { drop if
//    grp==\`i' }` — this fixture mirrors exactly that: two iterations' worth
//    of data_mutation blocks in ONE do_string response, only the LAST
//    carrying varlist_after. Must not break withMutationSummaries()'s
//    merge_counts/n_dropped/reshape decoration NOR applyDoResult()'s lastMut
//    varlist-refresh cheap path (which already optional-chains
//    `lastMut?.varlist_after` in the source — this suite is the executable
//    proof that guard actually holds end-to-end).
const b30MutObs = await (async () => {
  const obs = {};
  const settle = () => new Promise(r => setTimeout(r, 10));

  dom.window.pietNative = {
    request: async (key) => {
      switch (key) {
        // Deliberately agrees with the LAST mutation's varlist_after below —
        // both the cheap-path (lastMut) and the authoritative resync
        // (refreshVarlistAuthoritative(), which always runs too) should
        // converge on the same answer regardless of which settles first.
        case 'varlist':      return { varlist: [{ name: 'grp', dtype: 'f64', format: '%9.0g', label: '', n_missing: 0 }], n_rows: 5, n_cols: 1 };
        case 'history':      return { history: [] };
        case 'version':      return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        case 'do_string':
          return {
            blocks: [
              { type: 'echo', text: '.  forvalues i = 1/2 {' },
              // B.3.0/F8: iteration i=1's data_mutation — NO varlist_after
              // (coalesced away, not the loop's last), but n_dropped IS
              // present (withMutationSummaries's own field, independent of
              // varlist_after — `drop if` sets n_dropped, not dropped_vars).
              { type: 'data_mutation', action: 'drop', n_dropped: 3, n_rows_after: 7 },
              // iteration i=2's data_mutation — the loop's TRUE last
              // mutation, carries varlist_after as normal (F8 keeps it).
              { type: 'data_mutation', action: 'drop', n_dropped: 2, n_rows_after: 5, varlist_after: [{ name: 'grp', dtype: 'f64', format: '%9.0g', label: '', n_missing: 0 }] },
            ],
          };
        default: return {};
      }
    },
  };

  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
      <div id="doedit-overlay" class="console-overlay open">
        <div class="doedit-bar"><span class="doedit-title" id="doedit-title">Do-file Editor</span>
          <button id="doedit-run" type="button">Run</button>
        </div>
        <textarea id="doedit-text">forvalues i = 1/2 {
  drop if grp == \`i'
}</textarea>
      </div>
    </div>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span id="status-flash" hidden></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;

  let threw = false;
  const { init } = await import(JS('app.js'));
  try {
    await init();
    document.getElementById('doedit-run').click();
    await settle(); await settle();
  } catch {
    threw = true;
  }
  obs.threw = threw;

  const body = () => document.getElementById('console-body');
  obs.dropExtraTexts = [...body().querySelectorAll('.block-mutation, .block-display')]
    .map(el => el.textContent).filter(t => t.includes('observations deleted'));
  obs.varRowNames = [...document.querySelectorAll('.var-row')].map(tr => tr.dataset.varname);

  document.body.innerHTML = '';
  delete dom.window.pietNative;
  return obs;
})();

suite("B30-3 (bounded transcripts, contract_B 2.5.0): a data_mutation block missing `varlist_after` (F8-coalesced away within one loop body) never throws, still gets its withMutationSummaries decoration, and the loop's LAST mutation varlist_after still drives the card refresh", (ctx) => {
  check(ctx, b30MutObs.threw === false,
    'a do-run mixing a varlist_after-less mutation block with a normal one never throws');
  check(ctx, b30MutObs.dropExtraTexts.length === 2 &&
              b30MutObs.dropExtraTexts.includes('(3 observations deleted)') &&
              b30MutObs.dropExtraTexts.includes('(2 observations deleted)'),
    `BOTH iterations' n_dropped extras render — including i=1's, whose block has no varlist_after at all (got ${JSON.stringify(b30MutObs.dropExtraTexts)})`);
  check(ctx, b30MutObs.varRowNames.length === 1 && b30MutObs.varRowNames[0] === 'grp',
    `the Variables panel reflects the loop's LAST mutation's varlist_after ("grp") — the earlier missing-varlist_after block didn't corrupt the refresh (got ${JSON.stringify(b30MutObs.varRowNames)})`);
});


