// ════════════════════════════════════════════════════════════════════════════
// S6 (OVERHEAD-ZERO campaign) — drag-and-drop file open.
//   Two independently-testable halves, matching the feature's own two known
//   traps (see shell.cpp's installFileDropHandler() doc comment):
//     1. document-level dragover/drop listeners preventDefault() — proves
//        the JS half that stops WKWebView's "walks off to the file" default
//        action. What this CANNOT prove: that the native override actually
//        wins the race in a real WKWebView (jsdom has no WKWebView at all,
//        let alone AppKit drag-and-drop) — see the S6 report for what stays
//        unproven until a packaged-.app run.
//     2. a `{kind:"file_dropped", path}` pietEvents push (mirrors what
//        shell.cpp's native performDragOperation: override sends) routes
//        through onOpenFile(path) -> POST /api/open — the SAME wire call
//        the Recent-files reopen (openRecentFile() -> onOpenFile(knownPath))
//        and the toolbar picker (onOpenFile() -> pickFile() -> onOpenFile
//        (path)) both already use. What this CANNOT prove: the native
//        pasteboard extraction in shell.cpp (no AppKit in jsdom) — that's
//        the genuinely native half, unreachable from a headless JS harness.
// ════════════════════════════════════════════════════════════════════════════
const dropObs = await (async () => {
  const obs = {};
  const bridgeCalls = [];
  dom.window.pietNative = {
    request: async (key, body) => {
      bridgeCalls.push({ key, body });
      switch (key) {
        case 'varlist':  return { varlist: [], n_rows: 0, n_cols: 0 };
        case 'history':  return { history: [] };
        case 'version':  return { piet_version: '0.0.0-test', cobra_version: '0.0.0-test' };
        case 'run_progress': return { running: false, current_line: 0, total_lines: 0, current_cmd: '', elapsed_ms: 0 };
        case 'open':
          return { varlist_after: [{ name: 'price', dtype: 'f64', format: '%9.0g', label: '', n_missing: 0 }], n_rows_after: 74 };
        default: return {};
      }
    },
  };
  // Fake native push channel — mirrors window.pietEvents (see app.js's
  // initPietEventsBridge()), same idiom as the D9 request-dialog suite above.
  dom.window.pietEvents = new dom.window.EventTarget();

  document.body.innerHTML = `
    <div id="pane-console">
      <div id="console-wrap"><div id="console-empty"></div><div id="console-body"></div></div>
      <div id="cmd-bar"><input id="cmd-input" type="text"><button id="btn-run" type="button">Run</button></div>
    </div>
    <nav class="toolbar-menu">
      <div class="menu-dropdown">
        <a href="#" tabindex="0">File ▾</a>
        <div class="menu-dropdown-content">
          <div class="menu-recent-group" id="file-menu-recent-group" hidden>
            <div id="file-menu-recent"></div>
          </div>
        </div>
      </div>
    </nav>
    <div id="var-list-wrap"></div>
    <ul id="hist-list"></ul>
    <span id="status-file">(no data)</span><span id="status-dims"></span>
    <span class="kernel-dot" id="kernel-dot"></span>`;

  const { init } = await import(JS('app.js'));
  await init();
  const settle = () => new Promise((r) => setTimeout(r, 10));

  const openCalls = () => bridgeCalls.filter((c) => c.key === 'open');
  function pushDrop(detail) {
    dom.window.pietEvents.dispatchEvent(new dom.window.CustomEvent('piet-event', { detail }));
  }

  // ── Leg 1: dragover AND drop are both preventDefault()'d (trap #1). ──
  const overEvent = new dom.window.Event('dragover', { bubbles: true, cancelable: true });
  document.dispatchEvent(overEvent);
  obs.dragoverPrevented = overEvent.defaultPrevented;

  const dropEvent = new dom.window.Event('drop', { bubbles: true, cancelable: true });
  document.dispatchEvent(dropEvent);
  obs.dropPrevented = dropEvent.defaultPrevented;

  // ── Leg 2: a file_dropped push opens the file through the SAME route as
  //    the toolbar picker / Recent-files reopen (trap #2's native-hands-off
  //    half — see onOpenFile() in app.js). ──
  pushDrop({ kind: 'file_dropped', path: '/fake/dir/dropped.dta' });
  await settle();
  obs.openCallCount  = openCalls().length;
  obs.openBody       = openCalls()[0]?.body;
  obs.statusFileText = document.getElementById('status-file').textContent;
  obs.echoText = document.getElementById('console-body').querySelector('.block-echo')?.textContent ?? null;

  // Existing RunProgress-shaped (no "kind") pushes must not misfire this branch.
  pushDrop({ running: true, current_line: 1, total_lines: 2, current_cmd: '', elapsed_ms: 0 });
  await settle();
  obs.openCallCountAfterProgressPush = openCalls().length;

  // ── Defensive: a malformed push (kind present, path missing/empty) must
  //    NOT call open — and must NOT pop the native file picker either
  //    (onOpenFile() falls back to pickFile()/dialog.open when its argument
  //    is falsy; the app.js guard exists specifically to prevent that). ──
  pushDrop({ kind: 'file_dropped', path: '' });
  await settle();
  obs.openCallCountAfterEmptyPath = openCalls().length;
  obs.dialogOpenCallCount = bridgeCalls.filter((c) => c.key === 'dialog.open').length;

  // ── BUG-173 (W:P8): a dropped `.do` must go to the EDITOR, not the data
  //    loader. Before the fix onOpenFile() treated any non-.dta/.csv path as
  //    hbin, so dropping a do-file answered `bad magic (not a .hbin file)`.
  //    Load-only by design — a drop is one gesture with no confirm step. ──
  const openCallsBeforeDoDrop = openCalls().length;
  pushDrop({ kind: 'file_dropped', path: '/fake/dir/analysis.do' });
  await settle();
  obs.openCallsAfterDoDrop = openCalls().length - openCallsBeforeDoDrop;
  obs.fileReadAfterDoDrop = bridgeCalls.filter((c) => c.key === 'file.read').length;
  obs.doEditorTextAfterDrop = document.getElementById('doedit-text')?.value ?? null;
  obs.runDoCallsAfterDoDrop = bridgeCalls.filter((c) => c.key === 'run_do').length;

  // ── BUG-173 half two: an extension PIET does not open is named, not
  //    guessed at as hbin. ──
  const openCallsBeforeJunkDrop = openCalls().length;
  pushDrop({ kind: 'file_dropped', path: '/fake/dir/notes.pdf' });
  await settle();
  obs.openCallsAfterJunkDrop = openCalls().length - openCallsBeforeJunkDrop;
  obs.junkDropErrorText = [...document.getElementById('console-body').querySelectorAll('.block-error')]
    .map((e) => e.textContent).join(' | ');

  delete dom.window.pietNative;
  delete dom.window.pietEvents;
  document.body.innerHTML = '';
  return obs;
})();

suite('S6: drag-and-drop file open — dragover/drop preventDefault, file_dropped push routes through the SAME /api/open path as the picker', (ctx) => {
  check(ctx, dropObs.dragoverPrevented === true,
    'dragover is preventDefault()\'d (half of what stops WKWebView\'s default "navigate to the file" action)');
  check(ctx, dropObs.dropPrevented === true,
    'drop is ALSO preventDefault()\'d — dragover alone is not sufficient (the documented trap)');
  check(ctx, dropObs.openCallCount === 1, `a file_dropped push calls /api/open exactly once (got ${dropObs.openCallCount})`);
  check(ctx, dropObs.openCallsAfterDoDrop === 0,
    `BUG-173: dropping a .do makes ZERO /api/open (data-loader) calls (got ${dropObs.openCallsAfterDoDrop}) — it used to go to the hbin reader and answer "bad magic (not a .hbin file)"`);
  check(ctx, dropObs.fileReadAfterDoDrop >= 1,
    'BUG-173: dropping a .do reads it as SOURCE (file.read), the do-file-editor path');
  check(ctx, dropObs.runDoCallsAfterDoDrop === 0,
    'BUG-173: a dropped .do is LOADED, never executed — a drop is one gesture with no confirmation step');
  check(ctx, dropObs.openCallsAfterJunkDrop === 0,
    `BUG-173: dropping an unopenable extension makes no /api/open call (got ${dropObs.openCallsAfterJunkDrop})`);
  // The refusal may LIST .hbin as something droppable — that is the helpful
  // half. What it must never do is assert the dropped file is a broken hbin,
  // which is the pre-fix "bad magic (not a .hbin file)" shape.
  check(ctx, /\.pdf/.test(dropObs.junkDropErrorText ?? '') &&
             !/bad magic|not a \.hbin file/i.test(dropObs.junkDropErrorText ?? ''),
    `BUG-173: the refusal names the extension it got and never claims the file is a malformed hbin (got: ${JSON.stringify(dropObs.junkDropErrorText)})`);
  check(ctx, dropObs.openBody?.filepath === '/fake/dir/dropped.dta',
    `the dropped path is forwarded verbatim as filepath (got ${JSON.stringify(dropObs.openBody)})`);
  check(ctx, dropObs.openBody?.format === 'dta',
    'format is guessed from the extension by the SAME onOpenFile() logic the toolbar picker uses — no second/divergent format rule');
  check(ctx, dropObs.statusFileText.includes('dropped.dta'), 'the status bar reflects the opened file — same card as any other open');
  check(ctx, dropObs.echoText === '. use dropped.dta', `the console echoes "use <file>" exactly like any other open (got ${JSON.stringify(dropObs.echoText)})`);
  check(ctx, dropObs.openCallCountAfterProgressPush === 1, 'a shape-only RunProgress push does not re-trigger open (kind discriminator)');
  check(ctx, dropObs.openCallCountAfterEmptyPath === 1, 'a file_dropped push with an empty path is a no-op (defensive guard)');
  check(ctx, dropObs.dialogOpenCallCount === 0, 'the native file picker (dialog.open) is NEVER invoked by a drop — this is the knownPath leg, not the picker leg');
});

// ════════════════════════════════════════════════════════════════════════════
// P1-A2 (UX-052 back half) — the browse grid renders %t* columns as calendar
// text instead of the raw Stata family index.
//
//   Truth source: fixtures/stata_date_render.txt — StataNow 19.5 BE's OWN
//   display strings, captured by fixtures/stata_date_render.do. Nothing here
//   is a hand-typed date; every expectation is read out of that file, so a
//   wrong calendar cannot be "fixed" by editing the test.
//
//   These drive the REAL VirtualizedGrid (not fmtCellValue directly) so the
//   assertion covers the wiring — col.format reaching the cell — and not just
//   the pure function. The oracle's leading spaces are `display` padding to
//   the format width, not cell text; see the fixture header.
// ════════════════════════════════════════════════════════════════════════════
const { VirtualizedGrid } = await import(JS('grid.js'));

const DATE_ORACLE = readFileSync(resolve(__dirname, 'fixtures/stata_date_render.txt'), 'utf8')
  .split('\n')
  .map((l) => l.trimEnd())
  .filter((l) => l.startsWith('RENDER|'))
  .map((l) => { const f = l.split('|'); return { fmt: f[1], raw: Number(f[2]), text: f[3].trim() }; });

const DATE_FAMILIES = ['%td', '%tw', '%tm', '%tq', '%th', '%ty', '%tc'];

// The oracle file now carries three shapes of line, so each suite selects its
// own by an EXACT rule rather than by "whatever is left over" — a leftover
// filter silently swallows any future line class into the wrong suite (adding
// the %tc cases below would have landed them in the %td detail suite).
const DATE_DETAIL_CASES = DATE_ORACLE.filter((o) => o.fmt.startsWith('%td') && o.fmt !== '%td');
const COMMA_CASES = DATE_ORACLE.filter((o) => !o.fmt.startsWith('%t') && o.fmt.endsWith('c'));

// Build ONE grid whose columns are the six families and whose rows are the
// oracle's raw indices (shorter families pad with null → the grid's own "."
// missing-cell path, which these suites do not assert against).
const dateGridObs = await (async () => {
  const byFmt = new Map(DATE_FAMILIES.map((f) => [f, DATE_ORACLE.filter((o) => o.fmt === f)]));
  const nRows = Math.max(...DATE_FAMILIES.map((f) => byFmt.get(f).length));
  const columns = DATE_FAMILIES.map((f, k) => ({ name: `v${k}`, dtype: 'f64', format: f }));
  const rows = [];
  for (let r = 0; r < nRows; r++) rows.push(DATE_FAMILIES.map((f) => byFmt.get(f)[r]?.raw ?? null));

  const container = document.createElement('div');
  document.body.appendChild(container);
  let fetchCalls = 0;
  const grid = new VirtualizedGrid(container, async () => { fetchCalls++; return { columns, rows }; });
  await grid.load({ n_rows_total: nRows, columns, rows, windowed: true });

  const rowEls = [...container.querySelectorAll('.browser-row')];
  const cellText = (r, c) =>
    rowEls[r]?.querySelectorAll('.browser-cell:not(.browser-gutter)')[c]?.textContent ?? null;

  const observed = [];
  for (let c = 0; c < DATE_FAMILIES.length; c++) {
    const cases = byFmt.get(DATE_FAMILIES[c]);
    for (let r = 0; r < cases.length; r++) {
      observed.push({ ...cases[r], got: cellText(r, c) });
    }
  }
  container.remove();
  return { observed, nRows, byFmt, fetchCalls, renderedRows: rowEls.length };
})();

suite('P1-A2 (UX-052): browse grid decodes every %t* family to Stata calendar text (real Stata 19.5 oracle)', (ctx) => {
  check(ctx, dateGridObs.fetchCalls === 0,
    `the whole window is seeded — no /api/browse re-fetch could have supplied these cells (fetchPage calls: ${dateGridObs.fetchCalls})`);
  check(ctx, dateGridObs.renderedRows === dateGridObs.nRows,
    `all ${dateGridObs.nRows} fixture rows actually rendered (got ${dateGridObs.renderedRows}) — an unrendered row would make the per-case checks below vacuous`);
  for (const o of dateGridObs.observed) {
    check(ctx, o.got === o.text,
      `${o.fmt} index ${o.raw} renders as "${o.text}" (Stata's own string) — got ${JSON.stringify(o.got)}`);
  }
});

suite('P1-A2 (UX-052): the date oracle covers each family AND the pre-1960 (negative-index) arithmetic', (ctx) => {
  // Without this floor, a fixture that silently lost its cases would leave the
  // suite above green with nothing to check.
  for (const f of DATE_FAMILIES) {
    check(ctx, dateGridObs.byFmt.get(f).length >= 1, `oracle carries at least one ${f} case`);
  }
  // JS `%` keeps the dividend's sign, so an index before the 1960 epoch is
  // exactly where a truncating decode diverges from Stata (-1 → "1960w0"
  // instead of "1959w52"). Every offset family must pin that direction.
  for (const f of ['%td', '%tw', '%tm', '%tq', '%th']) {
    check(ctx, dateGridObs.byFmt.get(f).some((o) => o.raw < 0),
      `oracle carries a pre-epoch (negative index) ${f} case — the floor-vs-truncate discriminator`);
  }
  check(ctx, dateGridObs.byFmt.get('%tw').some((o) => o.text.endsWith('w52')),
    'oracle pins a week-52 case — the fixed-52-week year is what the ×7 bug got wrong (DESIGN-dates-fmt.md §3.2)');
  // Partition floor (P1-A2B): every RENDER line must be claimed by exactly one
  // of the three suites. Without this, a fixture line whose format matches no
  // selector is simply never rendered by anything and the file grows dead
  // cases that look like coverage.
  const claimed = new Set([
    ...DATE_ORACLE.filter((o) => DATE_FAMILIES.includes(o.fmt)),
    ...DATE_DETAIL_CASES, ...COMMA_CASES,
  ]);
  check(ctx, claimed.size === DATE_ORACLE.length,
    `every oracle line is claimed by exactly one suite (${claimed.size} claimed of ${DATE_ORACLE.length}) — an unclaimed line is a dead fixture case`);
});

// ════════════════════════════════════════════════════════════════════════════
// P1-A2B — %tc (millisecond clock) and the `c` thousands-comma suffix, the two
// UX-052 named residuals ① and ② that the P1-A2 rider left open.
//
//   %tc rides the suite above for its per-case render (it is in DATE_FAMILIES),
//   so what is left to pin here is the part a single correct string cannot
//   prove: that the sub-second remainder is TRUNCATED not rounded, that the
//   time-of-day fields are actually decoded, and that %tC still declines.
// ════════════════════════════════════════════════════════════════════════════
suite('P1-A2B (UX-052 ②): the %tc oracle pins sub-second truncation, the epoch, a pre-1960 instant and a real time-of-day', (ctx) => {
  const tc = dateGridObs.byFmt.get('%tc');
  check(ctx, tc.length >= 6, `oracle carries at least the 6 writer-Q6 datetime boundaries (got ${tc.length})`);
  // Truncation discriminator: two indices in the SAME second whose sub-second
  // remainders differ must render identically. A rounding decode splits them.
  const pairs = tc.filter((o) => o.raw !== 0 && Math.floor(o.raw / 1000) * 1000 !== o.raw);
  check(ctx, pairs.length >= 2,
    `oracle carries at least 2 sub-second (non-whole-second) indices — the truncate-vs-round discriminator (got ${pairs.length})`);
  for (const o of pairs) {
    const whole = tc.find((w) => w.raw === Math.floor(o.raw / 1000) * 1000);
    if (whole) {
      check(ctx, o.text === whole.text,
        `%tc ${o.raw} and its whole-second floor ${whole.raw} render identically ("${whole.text}") — Stata truncates the remainder, it does not round up`);
    }
  }
  check(ctx, tc.some((o) => o.raw < 0), '%tc oracle carries a pre-1960 instant — the floor-vs-truncate day split');
  check(ctx, tc.some((o) => /\s(?!00:00:00)\d{2}:\d{2}:\d{2}$/.test(o.text)),
    'oracle carries a non-midnight time-of-day — otherwise the hour/minute fields are never exercised');
  check(ctx, tc.every((o) => /^\d{2}[a-z]{3}\d{4} \d{2}:\d{2}:\d{2}$/.test(o.text)),
    'every %tc oracle string is the ddmonYYYY HH:MM:SS layout — a shape floor on the truth source itself');
});

const commaObs = await (async () => {
  const columns = COMMA_CASES.map((o, k) => ({ name: `c${k}`, dtype: 'f64', format: o.fmt }));
  const rows = [COMMA_CASES.map((o) => o.raw)];
  const container = document.createElement('div');
  document.body.appendChild(container);
  const grid = new VirtualizedGrid(container, async () => { throw new Error('no fetch expected'); });
  await grid.load({ n_rows_total: 1, columns, rows, windowed: true });
  const cells = [...container.querySelectorAll('.browser-row')][0]
    ?.querySelectorAll('.browser-cell:not(.browser-gutter)');
  const observed = COMMA_CASES.map((o, k) => ({ ...o, got: cells?.[k]?.textContent }));
  container.remove();
  return observed;
})();

suite('P1-A2B (UX-052 ①): the `c` suffix inserts Stata\'s thousands separators on both the g and f branches (real Stata 19.5 oracle)', (ctx) => {
  check(ctx, commaObs.length >= 4, `oracle carries at least 4 comma-suffix cases (got ${commaObs.length})`);
  for (const o of commaObs) {
    check(ctx, o.got === o.text,
      `${o.fmt} of ${o.raw} renders as "${o.text}" (Stata's own string) — got ${JSON.stringify(o.got)}`);
  }
  // Branch + boundary coverage floors: one branch or the sub-1000 case going
  // missing would leave every remaining assertion above still green.
  check(ctx, commaObs.some((o) => /gc$/.test(o.fmt)), 'oracle exercises the g branch (%#.#gc)');
  check(ctx, commaObs.some((o) => /fc$/.test(o.fmt)), 'oracle exercises the f branch (%#.#fc)');
  check(ctx, commaObs.some((o) => Math.abs(o.raw) < 1000),
    'oracle exercises a magnitude below 1000 — the case that must gain NO separator');
  check(ctx, commaObs.some((o) => o.raw < 0), 'oracle exercises a negative value — the sign must not be chunked with the digits');
});

// A15's numeric branches must survive the %t* branch being added in front of
// them, and %tc/%tC must keep falling through (out of this rider's scope).
const dateNonRegressionObs = await (async () => {
  const columns = [
    { name: 'fixed', dtype: 'f64', format: '%9.2f' },
    { name: 'gen',   dtype: 'f64', format: '%8.0g' },
    { name: 'none',  dtype: 'f64' },
    { name: 'leap',  dtype: 'f64', format: '%tC' },
    { name: 'miss',  dtype: 'f64', format: '%td' },
    { name: 'plaing', dtype: 'f64', format: '%12.0g' },
    { name: 'plainf', dtype: 'f64', format: '%12.2f' },
  ];
  const rows = [[1.37, 1.37, 1.37, 0, null, 1234567, 1234567]];
  const container = document.createElement('div');
  document.body.appendChild(container);
  const grid = new VirtualizedGrid(container, async () => { throw new Error('no fetch expected'); });
  await grid.load({ n_rows_total: 1, columns, rows, windowed: true });
  const cells = [...container.querySelectorAll('.browser-row')][0]
    ?.querySelectorAll('.browser-cell:not(.browser-gutter)');
  const obs = {
    fixed: cells?.[0]?.textContent, gen: cells?.[1]?.textContent, none: cells?.[2]?.textContent,
    leap: cells?.[3]?.textContent, miss: cells?.[4]?.textContent,
    missClass: cells?.[4]?.className,
    plaing: cells?.[5]?.textContent, plainf: cells?.[6]?.textContent,
  };
  container.remove();
  return obs;
})();

suite('P1-A2 (UX-052) non-regression: A15 numeric branches and the %tc/%tC scope boundary are untouched', (ctx) => {
  check(ctx, dateNonRegressionObs.fixed === '1.37', `%9.2f still renders fixed decimals (got ${JSON.stringify(dateNonRegressionObs.fixed)})`);
  check(ctx, dateNonRegressionObs.gen === fmtG(1.37), `%8.0g still goes through fmtG (got ${JSON.stringify(dateNonRegressionObs.gen)})`);
  check(ctx, dateNonRegressionObs.none === fmtG(1.37), `a format-less column still goes through fmtG (got ${JSON.stringify(dateNonRegressionObs.none)})`);
  // P1-A2B moved %tc into the decoded set; %tC did NOT move — it is %tc plus
  // the leap-second table, and a decode without that table would be silently
  // wrong by whole seconds rather than visibly unhandled. This check is the
  // scope boundary: the branch must recognize the family, DECLINE it, and fall
  // through WITHOUT throwing.
  check(ctx, dateNonRegressionObs.leap === fmtG(0),
    `%tC is declined by the date branch and falls through to fmtG, no throw (got ${JSON.stringify(dateNonRegressionObs.leap)})`);
  check(ctx, dateNonRegressionObs.miss === '.' && /cell-missing/.test(dateNonRegressionObs.missClass ?? ''),
    'a missing value in a %td column is still the "." missing cell — the date branch never runs on it');
  // The comma suffix must be opt-in: the SAME magnitude through a suffix-less
  // format keeps its bare digits. Without this pair, _groupThousands could be
  // grouping unconditionally and every comma assertion would still pass.
  check(ctx, dateNonRegressionObs.plaing === fmtG(1234567),
    `%12.0g (no c suffix) gets NO separators (got ${JSON.stringify(dateNonRegressionObs.plaing)})`);
  check(ctx, dateNonRegressionObs.plainf === '1234567.00',
    `%12.2f (no c suffix) gets NO separators (got ${JSON.stringify(dateNonRegressionObs.plainf)})`);
});

// ════════════════════════════════════════════════════════════════════════════
// FIX:GRID-TFMT-DETAIL — a %td format carrying a detail string (`%tdNN/DD/CCYY`,
// `%tdMonth_dd,_CCYY`, …) now renders via the token map (fmtTdDetail in
// grid.js) instead of falling back to the family-default layout. Same truth-
// source discipline as the suite above: every case is read out of the oracle
// (fixtures/stata_date_render.txt, the block appended below the family cases),
// nothing here is a hand-typed date. %tc/%tC detail strings are NOT covered —
// those families stay entirely out of scope (see the non-regression suite
// above), so this rider only ever looks at `%td`.
// ════════════════════════════════════════════════════════════════════════════
// (DATE_DETAIL_CASES is selected up with the other two partitions — it used to
// be "everything that is not a bare family", which would have swallowed the
// P1-A2B %tc and comma lines.)
const dateDetailObs = await (async () => {
  const columns = DATE_DETAIL_CASES.map((o, k) => ({ name: `d${k}`, dtype: 'f64', format: o.fmt }));
  const rows = [DATE_DETAIL_CASES.map((o) => o.raw)];
  const container = document.createElement('div');
  document.body.appendChild(container);
  const grid = new VirtualizedGrid(container, async () => { throw new Error('no fetch expected'); });
  await grid.load({ n_rows_total: 1, columns, rows, windowed: true });
  const cells = [...container.querySelectorAll('.browser-row')][0]
    ?.querySelectorAll('.browser-cell:not(.browser-gutter)');
  const observed = DATE_DETAIL_CASES.map((o, k) => ({ ...o, got: cells?.[k]?.textContent }));
  container.remove();
  return observed;
})();

suite('FIX:GRID-TFMT-DETAIL: %td detail-string token map renders Stata\'s exact layout (real Stata 19.5 oracle)', (ctx) => {
  check(ctx, dateDetailObs.length >= 4, `oracle carries at least 4 detail-string cases (got ${dateDetailObs.length})`);
  for (const o of dateDetailObs) {
    check(ctx, o.got === o.text,
      `${o.fmt} index ${o.raw} renders as "${o.text}" (Stata's own string) — got ${JSON.stringify(o.got)}`);
  }
  // Token-class coverage floor: a fixture that silently dropped a token class
  // would leave this suite green while exercising nothing for it.
  const fmtsJoined = DATE_DETAIL_CASES.map((o) => o.fmt).join(' ');
  for (const tok of ['CCYY', 'NN', 'DD', 'dd', 'Mon', 'Month', 'YY', '_']) {
    check(ctx, fmtsJoined.includes(tok), `oracle exercises the ${tok} detail token at least once`);
  }
});

// ════════════════════════════════════════════════════════════════════════════
// NEGATIVE-CONTROL SELF-TEST (DOM_RUNNER_SELFTEST=1)
//   Injects one deliberately-wrong assertion to prove the runner exits 1 (RED).
//   When env var is unset the suite is skipped. Run with:
//     DOM_RUNNER_SELFTEST=1 node dom_runner.mjs   → must exit 1
// ════════════════════════════════════════════════════════════════════════════
if (process.env.DOM_RUNNER_SELFTEST === '1') {
  suite('SELFTEST: negative-control — deliberate wrong assertion (must turn RED)', (ctx) => {
    // logit is an MLE estimator → must show P>|z|. Asserting P>|t| is deliberately wrong.
    const block = loadFix('dom/logit_estimation.json');
    const text  = formatEstimation(block);
    check(ctx, text.includes('P>|t|'),
      'SELFTEST: logit DELIBERATELY asserted to show P>|t| (this MUST fail — proves runner can go RED)');
  });
}

// ── suite-registration floor (REDTEAM-P2 blind spot ③, GATE-FALSIFICATION §3c) ──
//   A missing manifest name is a suite that silently stopped registering — RED,
//   independent of the check count. A NEW name that isn't in the manifest yet is
//   expected growth (573→583→593 must keep working), not a failure — it's only
//   noted, so the floor can never block a suite being added. Regenerate the
//   manifest deliberately after an intentional add/remove/rename:
//     DOM_RUNNER_UPDATE_MANIFEST=1 node dom_runner.mjs
const registeredSuiteNames = results.filter((r) => r[0] === 'SUITE').map((r) => r[1]);
let missingSuites = [];
if (process.env.DOM_RUNNER_UPDATE_MANIFEST === '1') {
  writeFileSync(SUITE_MANIFEST, JSON.stringify(registeredSuiteNames, null, 2) + '\n');
  console.log(`\x1b[33mMANIFEST UPDATED — ${registeredSuiteNames.length} suite name(s) written to ${SUITE_MANIFEST}\x1b[0m\n`);
} else if (existsSync(SUITE_MANIFEST)) {
  const expectedSuiteNames = JSON.parse(readFileSync(SUITE_MANIFEST, 'utf8'));
  const actual = new Set(registeredSuiteNames);
  missingSuites = expectedSuiteNames.filter((name) => !actual.has(name));
  const addedSuites = registeredSuiteNames.filter((name) => !new Set(expectedSuiteNames).has(name));
  if (addedSuites.length > 0) {
    console.log(`\x1b[33m  note: ${addedSuites.length} new suite(s) not yet in the manifest — run DOM_RUNNER_UPDATE_MANIFEST=1 to record them\x1b[0m`);
  }
}

// ── report ────────────────────────────────────────────────────────────────────
for (const [tag, name, msg] of results) {
  if (tag === 'SUITE') {
    const ok = msg === 'green';
    console.log(`${ok ? '\x1b[32m▣' : '\x1b[31m▤'} ${name} — ${msg}\x1b[0m`);
  } else if (tag === 'FAIL' || tag === 'THROW') {
    console.log(`  \x1b[31m✗ ${msg}\x1b[0m`);
  }
}
for (const name of missingSuites) {
  console.log(`  \x1b[31m✗ MISSING SUITE: "${name}" is in the manifest but did not run this pass\x1b[0m`);
}
console.log('');
const clean = FAILS === 0 && missingSuites.length === 0;
const verdict = clean
  ? `\x1b[32mDOM RUNNER GREEN — ${PASSES} checks passed, 0 failed\x1b[0m`
  : `\x1b[31mDOM RUNNER RED — ${FAILS} failed, ${PASSES} passed${missingSuites.length ? `, ${missingSuites.length} suite(s) missing` : ''}\x1b[0m`;
console.log(verdict);
process.exit(clean ? 0 : 1);
